#!/usr/bin/env python3
"""Merge report_part1.pdf and report_part2.pdf (in that order) into combined_report.pdf.

Pure standard-library PDF merger. Handles:
  - classic xref tables and xref streams (with /Prev chains)
  - object streams (/ObjStm) via FlateDecode (+ PNG predictors)
  - indirect /Length resolution
Strategy: copy every live object from both inputs with renumbered IDs, expand
object-stream members to classic objects, reparent the two page-tree roots under
a new root /Pages, and emit a fresh classic xref + trailer. The output is then
re-parsed to validate page count and structure.
"""
import os
import re
import sys
import zlib

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"
TMP_FILE = OUTPUT_FILE + ".tmp"

class ParseError(Exception):
    pass


# ---------------------------------------------------------------- low-level PDF tokenizing

def skip_ws_comments(data, pos):
    n = len(data)
    while pos < n:
        c = data[pos]
        if c in b"\x00\t\n\f\r ":
            pos += 1
        elif c == ord("%"):
            j = data.find(b"\n", pos)
            pos = n if j == -1 else j + 1
        else:
            break
    return pos


def scan_literal_string(data, pos):
    i = pos + 1
    depth = 1
    n = len(data)
    while i < n:
        c = data[i]
        if c == ord("\\"):
            i = min(i + 2, n)
            continue
        if c == ord("("):
            depth += 1
        elif c == ord(")"):
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    return n


def scan_hex_string(data, pos):
    i = data.find(b">", pos + 1)
    return len(data) if i == -1 else i + 1


def scan_name(data, pos):
    i = pos + 1
    n = len(data)
    while i < n and data[i] not in b"\x00\t\n\f\r ()<>[]{}/%":
        i += 1
    return i


def scan_primitive(data, pos):
    m = re.match(rb"\d+\s+\d+\s+R(?![A-Za-z0-9/])", data[pos:pos + 64])
    if m:
        return pos + m.end()
    m = re.match(rb"[+-]?(?:\d+\.?\d*|\.\d+)", data[pos:pos + 64])
    if m:
        return pos + m.end()
    i = pos
    n = len(data)
    while i < n and data[i] not in b"\x00\t\n\f\r ()<>[]{}/%":
        i += 1
    return i


def scan_object(data, pos):
    """Return the position just after one complete PDF object starting at pos."""
    pos = skip_ws_comments(data, pos)
    if pos >= len(data):
        return pos
    c = data[pos]
    if c == ord("("):
        return scan_literal_string(data, pos)
    if c == ord("<"):
        if data[pos + 1:pos + 2] == b"<":
            pos += 2
            while True:
                pos = skip_ws_comments(data, pos)
                if pos >= len(data):
                    return pos
                if data[pos:pos + 2] == b">>":
                    return pos + 2
                c2 = data[pos]
                if c2 == ord("("):
                    pos = scan_literal_string(data, pos)
                elif c2 == ord("<"):
                    pos = scan_object(data, pos)
                elif c2 == ord("["):
                    pos = scan_object(data, pos)
                elif c2 == ord("]"):
                    pos += 1
                elif c2 == ord(">"):
                    pos += 1
                else:
                    pos = scan_primitive(data, pos)
        else:
            return scan_hex_string(data, pos)
    if c == ord("["):
        pos += 1
        while True:
            pos = skip_ws_comments(data, pos)
            if pos >= len(data):
                return pos
            if data[pos] == ord("]"):
                return pos + 1
            pos = scan_object(data, pos)
    if c == ord("/"):
        return scan_name(data, pos)
    if c == ord(">"):
        return pos + 1
    return scan_primitive(data, pos)


def parse_dict_bytes(db):
    """Parse '<< ... >>' bytes into a list of (key, value_bytes) pairs."""
    pairs = []
    pos = skip_ws_comments(db, 0)
    if db[pos:pos + 2] != b"<<":
        return pairs
    pos += 2
    while True:
        pos = skip_ws_comments(db, pos)
        if pos >= len(db) or db[pos:pos + 2] == b">>":
            break
        if db[pos] == ord("/"):
            key_end = scan_name(db, pos)
            key = db[pos + 1:key_end]
            vpos = skip_ws_comments(db, key_end)
            vend = scan_object(db, vpos)
            pairs.append((key, db[vpos:vend]))
            pos = vend
        else:
            pos = scan_object(db, pos)
    return pairs


def dict_get(pairs, key):
    for k, v in pairs:
        if k == key:
            return v
    return None


def ref_of(value):
    if value is None:
        return None
    m = re.match(rb"(\d+)\s+(\d+)\s+R", value.strip())
    return (int(m.group(1)), int(m.group(2))) if m else None


def int_of(value):
    if value is None:
        return None
    m = re.match(rb"(\d+)", value.strip())
    return int(m.group(1)) if m else None


def name_of(value):
    if value is None:
        return None
    value = value.strip()
    return value if value.startswith(b"/") else None


def ints_of(value):
    return [int(x) for x in re.findall(rb"\d+", value or b"")]


# ---------------------------------------------------------------- compression helpers

def inflate(data_bytes):
    try:
        return zlib.decompress(data_bytes)
    except zlib.error:
        return zlib.decompress(data_bytes, -15)


def png_unpredict(data, columns, colors, bpc):
    bpp = max(1, (colors * bpc + 7) // 8)
    rowlen = max(1, (columns * colors * bpc + 7) // 8)
    out = bytearray()
    prev = bytearray(rowlen)
    i = 0
    n = len(data)
    while i < n:
        f = data[i]
        i += 1
        row = bytearray(data[i:i + rowlen])
        i += rowlen
        if len(row) < rowlen:
            row += b"\x00" * (rowlen - len(row))
        if f == 1:
            for j in range(bpp, rowlen):
                row[j] = (row[j] + row[j - bpp]) & 0xFF
        elif f == 2:
            for j in range(rowlen):
                row[j] = (row[j] + prev[j]) & 0xFF
        elif f == 3:
            for j in range(rowlen):
                a = row[j - bpp] if j >= bpp else 0
                row[j] = (row[j] + ((a + prev[j]) >> 1)) & 0xFF
        elif f == 4:
            for j in range(rowlen):
                a = row[j - bpp] if j >= bpp else 0
                b = prev[j]
                c = prev[j - bpp] if j >= bpp else 0
                p = a + b - c
                pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
                pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                row[j] = (row[j] + pr) & 0xFF
        out += row
        prev = row
    return bytes(out)


def decode_stream_data(stream_bytes, pairs):
    filt = dict_get(pairs, b"Filter")
    if filt is not None and filt not in (b"FlateDecode", b"[FlateDecode]"):
        if not (filt.startswith(b"[") and b"FlateDecode" in filt):
            raise ParseError("unsupported stream filter: %r" % filt)
    raw = inflate(stream_bytes)
    dp = dict_get(pairs, b"DecodeParms")
    if dp and dp.startswith(b"<<"):
        dpp = parse_dict_bytes(dp)
        pred = int_of(dict_get(dpp, b"Predictor")) or 1
        if pred >= 10:
            columns = int_of(dict_get(dpp, b"Columns")) or 1
            colors = int_of(dict_get(dpp, b"Colors")) or 1
            bpc = int_of(dict_get(dpp, b"BitsPerComponent")) or 8
            raw = png_unpredict(raw, columns, colors, bpc)
    return raw


# ---------------------------------------------------------------- object access

def read_stream(data, dict_bytes, stream_pos, ctx):
    """Return stream data bytes for an object whose 'stream' keyword is at stream_pos."""
    eol = stream_pos + 6
    if data[eol:eol + 2] == b"\r\n":
        eol += 2
    elif eol < len(data) and data[eol] in (10, 13):
        eol += 1
    pairs = parse_dict_bytes(dict_bytes)
    len_val = dict_get(pairs, b"Length")
    length = None
    if len_val is not None:
        r = ref_of(len_val)
        if r:
            if ctx is not None:
                try:
                    c = ctx_get_content(ctx, r[0])
                    length = int_of(c["dict"].strip())
                except Exception:
                    length = None
        else:
            length = int_of(len_val)
    if length is not None:
        stream_bytes = data[eol:eol + length]
        after = skip_ws_comments(data, eol + length)
        if data[after:after + 9] == b"endstream":
            return stream_bytes
    idx = data.find(b"endstream", eol)
    if idx == -1:
        raise ParseError("endstream not found")
    sb = data[eol:idx]
    while sb.endswith((b"\n", b"\r")):
        sb = sb[:-1]
    return sb


def extract_type1(ctx, objnum, offset):
    data = ctx["data"]
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[offset:offset + 64])
    if not m or int(m.group(1)) != objnum:
        raise ParseError("object %d not found at offset %d" % (objnum, offset))
    bs = offset + m.end()
    bs = skip_ws_comments(data, bs)
    if data[bs:bs + 2] == b"<<":
        dict_end = scan_object(data, bs)
        dict_bytes = data[bs:dict_end]
        sk = skip_ws_comments(data, dict_end)
        if data[sk:sk + 6] == b"stream":
            return {"kind": "stream", "dict": dict_bytes,
                    "stream": read_stream(data, dict_bytes, sk, ctx)}
        eo = data.find(b"endobj", dict_end)
        if eo == -1:
            raise ParseError("endobj not found for object %d" % objnum)
        return {"kind": "dict", "dict": data[bs:eo].rstrip(b"\x00\t\n\f\r ")}
    eo = data.find(b"endobj", bs)
    if eo == -1:
        raise ParseError("endobj not found for object %d" % objnum)
    return {"kind": "dict", "dict": data[bs:eo].rstrip(b"\x00\t\n\f\r ")}


def ctx_get_content(ctx, num):
    cache = ctx["cache"]
    if num in cache:
        return cache[num]
    entry = ctx["objmap"].get(num)
    if entry is None:
        raise ParseError("object %d not present in xref" % num)
    if entry[0] == "direct":
        content = extract_type1(ctx, num, entry[1])
    else:
        stmnum, idx = entry[1], entry[2]
        ctx["skipped"].add(stmnum)
        stm = ctx_get_content(ctx, stmnum)
        if stm["kind"] != "stream":
            raise ParseError("object stream %d is not a stream" % stmnum)
        pairs = parse_dict_bytes(stm["dict"])
        n = int_of(dict_get(pairs, b"N")) or 0
        first = int_of(dict_get(pairs, b"First")) or 0
        raw = decode_stream_data(stm["stream"], pairs)
        toks = re.findall(rb"\d+", raw[:first])
        offs = [int(toks[i + 1]) for i in range(0, min(2 * n, len(toks) - 1), 2)]
        if idx >= len(offs):
            raise ParseError("object stream index out of range (obj %d)" % num)
        start = first + offs[idx]
        end = scan_object(raw, start)
        content = {"kind": "dict", "dict": raw[start:end].strip()}
    cache[num] = content
    return content


# ---------------------------------------------------------------- xref parsing

def parse_classic_xref(data, pos):
    objmap = {}
    p = data.find(b"xref", pos)
    if p == -1:
        raise ParseError("classic xref not found at %d" % pos)
    p += 4
    while True:
        p = skip_ws_comments(data, p)
        if data[p:p + 7] == b"trailer":
            break
        m = re.match(rb"(\d+)\s+(\d+)\s+", data[p:p + 64])
        if not m:
            break
        start = int(m.group(1))
        count = int(m.group(2))
        p += m.end()
        for _ in range(count):
            p = skip_ws_comments(data, p)
            m2 = re.match(rb"(\d+)\s+(\d+)\s+([nf])", data[p:p + 64])
            if not m2:
                raise ParseError("bad xref entry near %d" % p)
            offset = int(m2.group(1))
            typ = m2.group(3)
            if typ == b"n" and offset > 0:
                objmap[start] = ("direct", offset)
            start += 1
            p += m2.end()
    t = data.find(b"trailer", p)
    if t == -1:
        raise ParseError("trailer keyword not found")
    ts = data.find(b"<<", t)
    te = data.find(b">>", ts)
    trailer_raw = data[ts:te + 2]
    return objmap, parse_dict_bytes(trailer_raw)


def parse_xref_stream(data, pos):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[pos:pos + 64])
    if not m:
        raise ParseError("xref stream object header not found at %d" % pos)
    xref_objnum = int(m.group(1))
    body_start = pos + m.end()
    bs = skip_ws_comments(data, body_start)
    dict_end = scan_object(data, bs)
    dict_bytes = data[bs:dict_end]
    pairs = parse_dict_bytes(dict_bytes)
    sk = skip_ws_comments(data, dict_end)
    stream_bytes = read_stream(data, dict_bytes, sk, None)
    raw = decode_stream_data(stream_bytes, pairs)
    w = ints_of(dict_get(pairs, b"W")) or [1, 4, 2]
    if len(w) < 2:
        w = [1, 4, 2]
    size = int_of(dict_get(pairs, b"Size")) or 0
    idx_vals = ints_of(dict_get(pairs, b"Index")) or [0, size]
    prev = int_of(dict_get(pairs, b"Prev"))
    elen = sum(w)
    objmap = {}
    p = 0
    for k in range(0, len(idx_vals), 2):
        start = idx_vals[k]
        cnt = idx_vals[k + 1] if k + 1 < len(idx_vals) else 0
        for i in range(cnt):
            if p + elen > len(raw):
                break
            entry = raw[p:p + elen]
            p += elen
            t = 1 if w[0] == 0 else int.from_bytes(entry[:w[0]], "big")
            f2 = 0 if w[1] == 0 else int.from_bytes(entry[w[0]:w[0] + w[1]], "big")
            f3 = 0
            if len(w) > 2 and w[2] > 0:
                f3 = int.from_bytes(entry[w[0] + w[1]:w[0] + w[1] + w[2]], "big")
            onum = start + i
            if t == 1:
                objmap[onum] = ("direct", f2)
            elif t == 2:
                objmap[onum] = ("objstm", f2, f3)
    return objmap, pairs, prev, xref_objnum


def parse_pdf(data):
    m = re.match(rb"%PDF-(\d)\.(\d)", data[:64])
    version_minor = int(m.group(2)) if m else 4
    sms = list(re.finditer(rb"startxref\s+(\d+)", data))
    if not sms:
        raise ParseError("no startxref found")
    xref_pos = int(sms[-1].group(1))
    objmap = {}
    trailer_pairs = None
    skipped = set()
    pos = xref_pos
    seen = set()
    while pos and pos not in seen:
        seen.add(pos)
        if data[pos:pos + 4] == b"xref":
            m2, tp = parse_classic_xref(data, pos)
            prev = int_of(dict_get(tp, b"Prev"))
        else:
            m2, tp, prev, xnum = parse_xref_stream(data, pos)
            skipped.add(xnum)
        for k, v in m2.items():
            if k not in objmap:
                objmap[k] = v
        if trailer_pairs is None:
            trailer_pairs = tp
        pos = prev
    if dict_get(trailer_pairs, b"Encrypt") is not None:
        raise ParseError("encrypted PDFs are not supported")
    root_ref = ref_of(dict_get(trailer_pairs, b"Root"))
    if not root_ref:
        raise ParseError("no /Root in trailer")
    ctx = {"data": data, "objmap": objmap, "trailer": trailer_pairs,
           "version_minor": version_minor, "cache": {}, "skipped": skipped}
    catalog = ctx_get_content(ctx, root_ref[0])
    cpairs = parse_dict_bytes(catalog["dict"])
    pages_ref = ref_of(dict_get(cpairs, b"Pages"))
    if not pages_ref:
        raise ParseError("no /Pages in catalog")
    ctx["root"] = pages_ref[0]
    return ctx


# ---------------------------------------------------------------- page tree walking

def refs_from_value(ctx, value):
    if value is None:
        return []
    r = ref_of(value)
    if r:
        body = ctx_get_content(ctx, r[0])["dict"].strip()
        if body.startswith(b"["):
            return [int(x.group(1)) for x in re.finditer(rb"(\d+)\s+\d+\s+R", body)]
        return [r[0]]
    return [int(x.group(1)) for x in re.finditer(rb"(\d+)\s+\d+\s+R", value)]


def count_pages_ctx(ctx, node_num):
    content = ctx_get_content(ctx, node_num)
    pairs = parse_dict_bytes(content["dict"])
    typ = name_of(dict_get(pairs, b"Type"))
    if typ == b"Page":
        return 1
    kids = refs_from_value(ctx, dict_get(pairs, b"Kids"))
    return sum(count_pages_ctx(ctx, k) for k in kids)


# ---------------------------------------------------------------- serialization helpers

def rewrite_refs(data, mapping):
    """Copy bytes verbatim, replacing 'old 0 R' references outside strings/comments."""
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        c = data[i]
        if c == ord("%"):
            j = data.find(b"\n", i)
            j = n if j == -1 else j
            out += data[i:j]
            i = j
        elif c == ord("("):
            j = scan_literal_string(data, i)
            out += data[i:j]
            i = j
        elif c == ord("<"):
            if data[i + 1:i + 2] == b"<":
                out += data[i:i + 1]
                i += 1
            else:
                j = scan_hex_string(data, i)
                out += data[i:j]
                i = j
        elif c == ord(">") or c == ord("/") or c in b"[]":
            out += data[i:i + 1]
            i += 1
        elif c in b"0123456789+-.":
            m = re.match(rb"(\d+)\s+(\d+)\s+R(?![A-Za-z0-9/])", data[i:i + 64])
            if m and int(m.group(1)) in mapping:
                out += b"%d %d R" % (mapping[int(m.group(1))], int(m.group(2)))
                i += m.end()
                continue
            m2 = re.match(rb"[+-]?(?:\d+\.?\d*|\.\d+)", data[i:i + 64])
            if m2:
                out += data[i:i + m2.end()]
                i += m2.end()
                continue
            out += data[i:i + 1]
            i += 1
        else:
            out += data[i:i + 1]
            i += 1
    return bytes(out)


def set_length(dict_bytes, length):
    m = re.search(rb"/Length\s+(\d+)(?:\s+\d+\s+R)?", dict_bytes)
    repl = b"/Length " + str(length).encode()
    if m:
        return dict_bytes[:m.start()] + repl + dict_bytes[m.end():]
    idx = dict_bytes.rfind(b">>")
    return dict_bytes[:idx] + repl + b" " + dict_bytes[idx:]


def patch_parent(dict_bytes, newroot):
    m = re.search(rb"/Parent\s+\d+\s+\d+\s+R", dict_bytes)
    repl = b"/Parent " + str(newroot).encode() + b" 0 R"
    if m:
        return dict_bytes[:m.start()] + repl + dict_bytes[m.end():]
    idx = dict_bytes.rfind(b">>")
    return dict_bytes[:idx] + repl + b" " + dict_bytes[idx:]


# ---------------------------------------------------------------- merge

def build_output(ctxs, total_pages):
    roots = [ctx["root"] for ctx in ctxs]
    entries = []
    for ctx in ctxs:
        for oldnum in sorted(ctx["objmap"]):
            if oldnum in ctx["skipped"]:
                continue
            content = ctx_get_content(ctx, oldnum)
            if oldnum in ctx["skipped"]:
                continue
            entries.append((ctx, oldnum, content))
    mapping = {}
    for i, (_, oldnum, _) in enumerate(entries, start=1):
        mapping[oldnum] = i
    catalog_num = len(entries) + 1
    pages_num = len(entries) + 2

    out = bytearray()
    minor = max(ctx["version_minor"] for ctx in ctxs)
    out += b"%%PDF-1.%d\n" % max(4, minor)
    xref_offsets = {}
    for i, (ctx, oldnum, content) in enumerate(entries, start=1):
        xref_offsets[i] = len(out)
        body = rewrite_refs(content["dict"], mapping)
        if oldnum in roots:
            body = patch_parent(body, pages_num)
        if content["kind"] == "stream":
            sb = content["stream"]
            body = set_length(body, len(sb))
            out += b"%d 0 obj\n" % i + body + b"\nstream\n" + sb + b"\nendstream\nendobj\n"
        else:
            out += b"%d 0 obj\n" % i + body + b"\nendobj\n"
    xref_offsets[catalog_num] = len(out)
    out += (b"%d 0 obj\n<< /Type /Catalog /Pages %d 0 R >>\nendobj\n"
            % (catalog_num, pages_num))
    xref_offsets[pages_num] = len(out)
    kids = b" ".join(b"%d 0 R" % mapping[root] for root in roots)
    out += (b"%d 0 obj\n<< /Type /Pages /Kids [%s] /Count %d >>\nendobj\n"
            % (pages_num, kids, total_pages))
    xref_pos = len(out)
    count = pages_num + 1
    out += b"xref\n0 %d\n" % count
    out += b"0000000000 65535 f \n"
    for i in range(1, count):
        out += b"%010d 00000 n \n" % xref_offsets[i]
    trailer = b"<< /Size %d /Root %d 0 R" % (count, catalog_num)
    info_ref = ref_of(dict_get(ctxs[0]["trailer"], b"Info"))
    if info_ref and info_ref[0] in mapping:
        trailer += b" /Info %d 0 R" % mapping[info_ref[0]]
    trailer += b" >>"
    out += b"trailer\n" + trailer + b"\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    return bytes(out)


def main():
    ctxs = []
    for path in INPUT_FILES:
        with open(path, "rb") as fh:
            data = fh.read()
        if not data.startswith(b"%PDF-"):
            raise ParseError("%s is not a PDF file" % path)
        ctx = parse_pdf(data)
        ctx["pages"] = count_pages_ctx(ctx, ctx["root"])
        print("Parsed %s: %d objects, %d page(s), PDF-%d.%d"
              % (path, len(ctx["objmap"]), ctx["pages"], 1, ctx["version_minor"]))
        ctxs.append(ctx)

    total_pages = sum(c["pages"] for c in ctxs)
    result = build_output(ctxs, total_pages)
    with open(TMP_FILE, "wb") as fh:
        fh.write(result)
    os.replace(TMP_FILE, OUTPUT_FILE)

    # ---- self-validation: re-parse the produced file ----
    with open(OUTPUT_FILE, "rb") as fh:
        check_data = fh.read()
    check_ctx = parse_pdf(check_data)
    check_pages = count_pages_ctx(check_ctx, check_ctx["root"])
    assert check_pages == total_pages, (
        "validation failed: merged page count %d != expected %d" % (check_pages, total_pages))
    print("Created %s (%d bytes) with %d page(s); validation passed."
          % (OUTPUT_FILE, len(result), check_pages))
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as exc:  # noqa: BLE001 - report and exit cleanly
        if os.path.exists(TMP_FILE):
            os.remove(TMP_FILE)
        print("ERROR: %s" % exc, file=sys.stderr)
        sys.exit(1)

#!/usr/bin/env python3
"""Merge report_part1.pdf and report_part2.pdf (in that order) into combined_report.pdf.

Pure standard-library PDF merger. Handles:
  - classic xref tables and xref streams (with /Prev chains)
  - object streams (/ObjStm) via FlateDecode (+ PNG predictors)
  - indirect /Length resolution
Strategy: copy every live object from both inputs with renumbered IDs, expand
object-stream members to classic objects, reparent the two page-tree roots under
a new root /Pages, and emit a fresh classic xref + trailer. The output is then
re-parsed to validate page count and structure.
"""
import os
import re
import sys
import zlib

sys.setrecursionlimit(100000)

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"
TMP_FILE = OUTPUT_FILE + ".tmp"


def log(msg):
    print(msg, flush=True)


class ParseError(Exception):
    pass


# ---------------------------------------------------------------- low-level PDF tokenizing

def skip_ws_comments(data, pos):
    n = len(data)
    while pos < n:
        c = data[pos]
        if c in b"\x00\t\n\f\r ":
            pos += 1
        elif c == ord("%"):
            j = data.find(b"\n", pos)
            pos = n if j == -1 else j + 1
        else:
            break
    return pos


def scan_literal_string(data, pos):
    i = pos + 1
    depth = 1
    n = len(data)
    while i < n:
        c = data[i]
        if c == ord("\\"):
            i = min(i + 2, n)
            continue
        if c == ord("("):
            depth += 1
        elif c == ord(")"):
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    return n


def scan_hex_string(data, pos):
    i = data.find(b">", pos + 1)
    return len(data) if i == -1 else i + 1


def scan_name(data, pos):
    i = pos + 1
    n = len(data)
    while i < n and data[i] not in b"\x00\t\n\f\r ()<>[]{}/%":
        i += 1
    return i


def scan_primitive(data, pos):
    m = re.match(rb"\d+\s+\d+\s+R(?![A-Za-z0-9/])", data[pos:pos + 64])
    if m:
        return pos + m.end()
    m = re.match(rb"[+-]?(?:\d+\.?\d*|\.\d+)", data[pos:pos + 64])
    if m:
        return pos + m.end()
    i = pos
    n = len(data)
    while i < n and data[i] not in b"\x00\t\n\f\r ()<>[]{}/%":
        i += 1
    # Guarantee progress even for stray delimiter characters.
    return max(i, pos + 1)


def scan_object(data, pos):
    """Return the position just after one complete PDF object starting at pos."""
    pos = skip_ws_comments(data, pos)
    if pos >= len(data):
        return pos
    c = data[pos]
    if c == ord("("):
        return scan_literal_string(data, pos)
    if c == ord("<"):
        if data[pos + 1:pos + 2] == b"<":
            pos += 2
            while True:
                pos = skip_ws_comments(data, pos)
                if pos >= len(data):
                    return pos
                if data[pos:pos + 2] == b">>":
                    return pos + 2
                c2 = data[pos]
                if c2 == ord("("):
                    pos = scan_literal_string(data, pos)
                elif c2 == ord("<"):
                    pos = scan_object(data, pos)
                elif c2 == ord("["):
                    pos = scan_object(data, pos)
                elif c2 == ord("]"):
                    pos += 1
                elif c2 == ord(">"):
                    pos += 1
                else:
                    pos = scan_primitive(data, pos)
        else:
            return scan_hex_string(data, pos)
    if c == ord("["):
        pos += 1
        while True:
            pos = skip_ws_comments(data, pos)
            if pos >= len(data):
                return pos
            if data[pos] == ord("]"):
                return pos + 1
            pos = scan_object(data, pos)
    if c == ord("/"):
        return scan_name(data, pos)
    # Stray closers/delimiters: advance past them rather than looping.
    if c in b")]>}":
        return pos + 1
    return scan_primitive(data, pos)


def parse_dict_bytes(db):
    """Parse '<< ... >>' bytes into a list of (key, value_bytes) pairs."""
    pairs = []
    pos = skip_ws_comments(db, 0)
    if db[pos:pos + 2] != b"<<":
        return pairs
    pos += 2
    while True:
        pos = skip_ws_comments(db, pos)
        if pos >= len(db) or db[pos:pos + 2] == b">>":
            break
        if db[pos] == ord("/"):
            key_end = scan_name(db, pos)
            key = db[pos + 1:key_end]
            vpos = skip_ws_comments(db, key_end)
            vend = scan_object(db, vpos)
            if vend <= vpos:
                raise ParseError("no progress while parsing dict value")
            pairs.append((key, db[vpos:vend]))
            pos = vend
        else:
            newpos = scan_object(db, pos)
            if newpos <= pos:
                raise ParseError("no progress while parsing dict")
            pos = newpos
    return pairs


def dict_get(pairs, key):
    for k, v in pairs:
        if k == key:
            return v
    return None


def ref_of(value):
    if value is None:
        return None
    m = re.match(rb"(\d+)\s+(\d+)\s+R", value.strip())
    return (int(m.group(1)), int(m.group(2))) if m else None


def int_of(value):
    if value is None:
        return None
    m = re.match(rb"(\d+)", value.strip())
    return int(m.group(1)) if m else None


def name_of(value):
    if value is None:
        return None
    value = value.strip()
    return value if value.startswith(b"/") else None


def ints_of(value):
    return [int(x) for x in re.findall(rb"\d+", value or b"")]


# ---------------------------------------------------------------- compression helpers

def inflate(data_bytes):
    try:
        return zlib.decompress(data_bytes)
    except zlib.error:
        return zlib.decompress(data_bytes, -15)


def png_unpredict(data, columns, colors, bpc):
    bpp = max(1, (colors * bpc + 7) // 8)
    rowlen = max(1, (columns * colors * bpc + 7) // 8)
    out = bytearray()
    prev = bytearray(rowlen)
    i = 0
    n = len(data)
    while i < n:
        f = data[i]
        i += 1
        row = bytearray(data[i:i + rowlen])
        i += rowlen
        if len(row) < rowlen:
            row += b"\x00" * (rowlen - len(row))
        if f == 1:
            for j in range(bpp, rowlen):
                row[j] = (row[j] + row[j - bpp]) & 0xFF
        elif f == 2:
            for j in range(rowlen):
                row[j] = (row[j] + prev[j]) & 0xFF
        elif f == 3:
            for j in range(rowlen):
                a = row[j - bpp] if j >= bpp else 0
                row[j] = (row[j] + ((a + prev[j]) >> 1)) & 0xFF
        elif f == 4:
            for j in range(rowlen):
                a = row[j - bpp] if j >= bpp else 0
                b = prev[j]
                c = prev[j - bpp] if j >= bpp else 0
                p = a + b - c
                pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
                pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                row[j] = (row[j] + pr) & 0xFF
        out += row
        prev = row
    return bytes(out)


def decode_stream_data(stream_bytes, pairs):
    filt = dict_get(pairs, b"Filter")
    if filt is not None and filt not in (b"FlateDecode", b"[FlateDecode]"):
        if not (filt.startswith(b"[") and b"FlateDecode" in filt):
            raise ParseError("unsupported stream filter: %r" % filt)
    raw = inflate(stream_bytes)
    dp = dict_get(pairs, b"DecodeParms")
    if dp and dp.startswith(b"<<"):
        dpp = parse_dict_bytes(dp)
        pred = int_of(dict_get(dpp, b"Predictor")) or 1
        if pred >= 10:
            columns = int_of(dict_get(dpp, b"Columns")) or 1
            colors = int_of(dict_get(dpp, b"Colors")) or 1
            bpc = int_of(dict_get(dpp, b"BitsPerComponent")) or 8
            raw = png_unpredict(raw, columns, colors, bpc)
    return raw


# ---------------------------------------------------------------- object access

def read_stream(data, dict_bytes, stream_pos, ctx):
    """Return stream data bytes for an object whose 'stream' keyword is at stream_pos."""
    eol = stream_pos + 6
    if data[eol:eol + 2] == b"\r\n":
        eol += 2
    elif eol < len(data) and data[eol] in (10, 13):
        eol += 1
    pairs = parse_dict_bytes(dict_bytes)
    len_val = dict_get(pairs, b"Length")
    length = None
    if len_val is not None:
        r = ref_of(len_val)
        if r:
            if ctx is not None:
                try:
                    c = ctx_get_content(ctx, r[0])
                    length = int_of(c["dict"].strip())
                except Exception:
                    length = None
        else:
            length = int_of(len_val)
    if length is not None:
        stream_bytes = data[eol:eol + length]
        after = skip_ws_comments(data, eol + length)
        if data[after:after + 9] == b"endstream":
            return stream_bytes
    idx = data.find(b"endstream", eol)
    if idx == -1:
        raise ParseError("endstream not found")
    sb = data[eol:idx]
    while sb.endswith((b"\n", b"\r")):
        sb = sb[:-1]
    return sb


def extract_type1(ctx, objnum, offset):
    data = ctx["data"]
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[offset:offset + 64])
    if not m or int(m.group(1)) != objnum:
        raise ParseError("object %d not found at offset %d" % (objnum, offset))
    bs = offset + m.end()
    bs = skip_ws_comments(data, bs)
    if data[bs:bs + 2] == b"<<":
        dict_end = scan_object(data, bs)
        dict_bytes = data[bs:dict_end]
        sk = skip_ws_comments(data, dict_end)
        if data[sk:sk + 6] == b"stream":
            return {"kind": "stream", "dict": dict_bytes,
                    "stream": read_stream(data, dict_bytes, sk, ctx)}
        eo = data.find(b"endobj", dict_end)
        if eo == -1:
            raise ParseError("endobj not found for object %d" % objnum)
        return {"kind": "dict", "dict": data[bs:eo].rstrip(b"\x00\t\n\f\r ")}
    eo = data.find(b"endobj", bs)
    if eo == -1:
        raise ParseError("endobj not found for object %d" % objnum)
    return {"kind": "dict", "dict": data[bs:eo].rstrip(b"\x00\t\n\f\r ")}


def ctx_get_content(ctx, num):
    cache = ctx["cache"]
    if num in cache:
        return cache[num]
    entry = ctx["objmap"].get(num)
    if entry is None:
        raise ParseError("object %d not present in xref" % num)
    if entry[0] == "direct":
        content = extract_type1(ctx, num, entry[1])
    else:
        stmnum, idx = entry[1], entry[2]
        ctx["skipped"].add(stmnum)
        stm = ctx_get_content(ctx, stmnum)
        if stm["kind"] != "stream":
            raise ParseError("object stream %d is not a stream" % stmnum)
        pairs = parse_dict_bytes(stm["dict"])
        n = int_of(dict_get(pairs, b"N")) or 0
        first = int_of(dict_get(pairs, b"First")) or 0
        raw = decode_stream_data(stm["stream"], pairs)
        toks = re.findall(rb"\d+", raw[:first])
        offs = [int(toks[i + 1]) for i in range(0, min(2 * n, len(toks) - 1), 2)]
        if idx >= len(offs):
            raise ParseError("object stream index out of range (obj %d)" % num)
        start = first + offs[idx]
        end = scan_object(raw, start)
        content = {"kind": "dict", "dict": raw[start:end].strip()}
    cache[num] = content
    return content


# ---------------------------------------------------------------- xref parsing

def parse_classic_xref(data, pos):
    objmap = {}
    p = data.find(b"xref", pos)
    if p == -1:
        raise ParseError("classic xref not found at %d" % pos)
    p += 4
    while True:
        prev_p = p
        p = skip_ws_comments(data, p)
        if data[p:p + 7] == b"trailer":
            break
        m = re.match(rb"(\d+)\s+(\d+)\s+", data[p:p + 64])
        if not m:
            break
        start = int(m.group(1))
        count = int(m.group(2))
        p += m.end()
        for _ in range(count):
            p = skip_ws_comments(data, p)
            m2 = re.match(rb"(\d+)\s+(\d+)\s+([nf])", data[p:p + 64])
            if not m2:
                raise ParseError("bad xref entry near %d" % p)
            offset = int(m2.group(1))
            typ = m2.group(3)
            if typ == b"n" and offset > 0:
                objmap[start] = ("direct", offset)
            start += 1
            p += m2.end()
        if p == prev_p:
            raise ParseError("no progress while parsing classic xref")
    t = data.find(b"trailer", p)
    if t == -1:
        raise ParseError("trailer keyword not found")
    ts = data.find(b"<<", t)
    te = data.find(b">>", ts)
    trailer_raw = data[ts:te + 2]
    return objmap, parse_dict_bytes(trailer_raw)


def parse_xref_stream(data, pos):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[pos:pos + 64])
    if not m:
        raise ParseError("xref stream object header not found at %d" % pos)
    xref_objnum = int(m.group(1))
    body_start = pos + m.end()
    bs = skip_ws_comments(data, body_start)
    dict_end = scan_object(data, bs)
    dict_bytes = data[bs:dict_end]
    pairs = parse_dict_bytes(dict_bytes)
    sk = skip_ws_comments(data, dict_end)
    stream_bytes = read_stream(data, dict_bytes, sk, None)
    raw = decode_stream_data(stream_bytes, pairs)
    w = ints_of(dict_get(pairs, b"W")) or [1, 4, 2]
    if len(w) < 2:
        w = [1, 4, 2]
    size = int_of(dict_get(pairs, b"Size")) or 0
    idx_vals = ints_of(dict_get(pairs, b"Index")) or [0, size]
    prev = int_of(dict_get(pairs, b"Prev"))
    elen = sum(w)
    objmap = {}
    p = 0
    for k in range(0, len(idx_vals), 2):
        start = idx_vals[k]
        cnt = idx_vals[k + 1] if k + 1 < len(idx_vals) else 0
        for i in range(cnt):
            if p + elen > len(raw):
                break
            entry = raw[p:p + elen]
            p += elen
            t = 1 if w[0] == 0 else int.from_bytes(entry[:w[0]], "big")
            f2 = 0 if w[1] == 0 else int.from_bytes(entry[w[0]:w[0] + w[1]], "big")
            f3 = 0
            if len(w) > 2 and w[2] > 0:
                f3 = int.from_bytes(entry[w[0] + w[1]:w[0] + w[1] + w[2]], "big")
            onum = start + i
            if t == 1:
                objmap[onum] = ("direct", f2)
            elif t == 2:
                objmap[onum] = ("objstm", f2, f3)
    return objmap, pairs, prev, xref_objnum


def parse_pdf(data):
    m = re.match(rb"%PDF-(\d)\.(\d)", data[:64])
    version_minor = int(m.group(2)) if m else 4
    sms = list(re.finditer(rb"startxref\s+(\d+)", data))
    if not sms:
        raise ParseError("no startxref found")
    xref_pos = int(sms[-1].group(1))
    objmap = {}
    trailer_pairs = None
    skipped = set()
    pos = xref_pos
    seen = set()
    while pos and pos not in seen:
        seen.add(pos)
        if data[pos:pos + 4] == b"xref":
            m2, tp = parse_classic_xref(data, pos)
            prev = int_of(dict_get(tp, b"Prev"))
        else:
            m2, tp, prev, xnum = parse_xref_stream(data, pos)
            skipped.add(xnum)
        for k, v in m2.items():
            if k not in objmap:
                objmap[k] = v
        if trailer_pairs is None:
            trailer_pairs = tp
        pos = prev
    if dict_get(trailer_pairs, b"Encrypt") is not None:
        raise ParseError("encrypted PDFs are not supported")
    root_ref = ref_of(dict_get(trailer_pairs, b"Root"))
    if not root_ref:
        raise ParseError("no /Root in trailer")
    ctx = {"data": data, "objmap": objmap, "trailer": trailer_pairs,
           "version_minor": version_minor, "cache": {}, "skipped": skipped}
    catalog = ctx_get_content(ctx, root_ref[0])
    cpairs = parse_dict_bytes(catalog["dict"])
    pages_ref = ref_of(dict_get(cpairs, b"Pages"))
    if not pages_ref:
        raise ParseError("no /Pages in catalog")
    ctx["root"] = pages_ref[0]
    return ctx


# ---------------------------------------------------------------- page tree walking

def refs_from_value(ctx, value):
    if value is None:
        return []
    r = ref_of(value)
    if r:
        body = ctx_get_content(ctx, r[0])["dict"].strip()
        if body.startswith(b"["):
            return [int(x.group(1)) for x in re.finditer(rb"(\d+)\s+\d+\s+R", body)]
        return [r[0]]
    return [int(x.group(1)) for x in re.finditer(rb"(\d+)\s+\d+\s+R", value)]


def count_pages_ctx(ctx, node_num, depth=0):
    if depth > 100000:
        raise ParseError("page tree too deep (possible cycle)")
    content = ctx_get_content(ctx, node_num)
    pairs = parse_dict_bytes(content["dict"])
    typ = name_of(dict_get(pairs, b"Type"))
    if typ == b"Page":
        return 1
    kids = refs_from_value(ctx, dict_get(pairs, b"Kids"))
    return sum(count_pages_ctx(ctx, k, depth + 1) for k in kids)


# ---------------------------------------------------------------- serialization helpers

def rewrite_refs(data, mapping):
    """Copy bytes verbatim, replacing 'old 0 R' references outside strings/comments."""
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        c = data[i]
        if c == ord("%"):
            j = data.find(b"\n", i)
            j = n if j == -1 else j
            out += data[i:j]
            i = j
        elif c == ord("("):
            j = scan_literal_string(data, i)
            out += data[i:j]
            i = j
        elif c == ord("<"):
            if data[i + 1:i + 2] == b"<":
                out += data[i:i + 1]
                i += 1
            else:
                j = scan_hex_string(data, i)
                out += data[i:j]
                i = j
        elif c == ord(">") or c == ord("/") or c in b"[]":
            out += data[i:i + 1]
            i += 1
        elif c in b"0123456789+-.":
            m = re.match(rb"(\d+)\s+(\d+)\s+R(?![A-Za-z0-9/])", data[i:i + 64])
            if m and int(m.group(1)) in mapping:
                out += b"%d %d R" % (mapping[int(m.group(1))], int(m.group(2)))
                i += m.end()
                continue
            m2 = re.match(rb"[+-]?(?:\d+\.?\d*|\.\d+)", data[i:i + 64])
            if m2:
                out += data[i:i + m2.end()]
                i += m2.end()
                continue
            out += data[i:i + 1]
            i += 1
        else:
            out += data[i:i + 1]
            i += 1
    return bytes(out)


def set_length(dict_bytes, length):
    m = re.search(rb"/Length\s+(\d+)(?:\s+\d+\s+R)?", dict_bytes)
    repl = b"/Length " + str(length).encode()
    if m:
        return dict_bytes[:m.start()] + repl + dict_bytes[m.end():]
    idx = dict_bytes.rfind(b">>")
    return dict_bytes[:idx] + repl + b" " + dict_bytes[idx:]


def patch_parent(dict_bytes, newroot):
    m = re.search(rb"/Parent\s+\d+\s+\d+\s+R", dict_bytes)
    repl = b"/Parent " + str(newroot).encode() + b" 0 R"
    if m:
        return dict_bytes[:m.start()] + repl + dict_bytes[m.end():]
    idx = dict_bytes.rfind(b">>")
    return dict_bytes[:idx] + repl + b" " + dict_bytes[idx:]


# ---------------------------------------------------------------- merge

def build_output(ctxs, total_pages):
    roots = [ctx["root"] for ctx in ctxs]
    entries = []
    for ctx in ctxs:
        for oldnum in sorted(ctx["objmap"]):
            if oldnum in ctx["skipped"]:
                continue
            content = ctx_get_content(ctx, oldnum)
            if oldnum in ctx["skipped"]:
                continue
            entries.append((ctx, oldnum, content))
    mapping = {}
    for i, (_, oldnum, _) in enumerate(entries, start=1):
        mapping[oldnum] = i
    catalog_num = len(entries) + 1
    pages_num = len(entries) + 2

    out = bytearray()
    minor = max(ctx["version_minor"] for ctx in ctxs)
    out += b"%%PDF-1.%d\n" % max(4, minor)
    xref_offsets = {}
    for i, (ctx, oldnum, content) in enumerate(entries, start=1):
        xref_offsets[i] = len(out)
        body = rewrite_refs(content["dict"], mapping)
        if oldnum in roots:
            body = patch_parent(body, pages_num)
        if content["kind"] == "stream":
            sb = content["stream"]
            body = set_length(body, len(sb))
            out += b"%d 0 obj\n" % i + body + b"\nstream\n" + sb + b"\nendstream\nendobj\n"
        else:
            out += b"%d 0 obj\n" % i + body + b"\nendobj\n"
    xref_offsets[catalog_num] = len(out)
    out += (b"%d 0 obj\n<< /Type /Catalog /Pages %d 0 R >>\nendobj\n"
            % (catalog_num, pages_num))
    xref_offsets[pages_num] = len(out)
    kids = b" ".join(b"%d 0 R" % mapping[root] for root in roots)
    out += (b"%d 0 obj\n<< /Type /Pages /Kids [%s] /Count %d >>\nendobj\n"
            % (pages_num, kids, total_pages))
    xref_pos = len(out)
    count = pages_num + 1
    out += b"xref\n0 %d\n" % count
    out += b"0000000000 65535 f \n"
    for i in range(1, count):
        out += b"%010d 00000 n \n" % xref_offsets[i]
    trailer = b"<< /Size %d /Root %d 0 R" % (count, catalog_num)
    info_ref = ref_of(dict_get(ctxs[0]["trailer"], b"Info"))
    if info_ref and info_ref[0] in mapping:
        trailer += b" /Info %d 0 R" % mapping[info_ref[0]]
    trailer += b" >>"
    out += b"trailer\n" + trailer + b"\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    return bytes(out)


def main():
    ctxs = []
    for path in INPUT_FILES:
        log("[stage] reading %s" % path)
        with open(path, "rb") as fh:
            data = fh.read()
        if not data.startswith(b"%PDF-"):
            raise ParseError("%s is not a PDF file" % path)
        log("[stage] parsing %s (%d bytes)" % (path, len(data)))
        ctx = parse_pdf(data)
        log("[stage] counting pages in %s" % path)
        ctx["pages"] = count_pages_ctx(ctx, ctx["root"])
        log("Parsed %s: %d objects, %d page(s), PDF-%d.%d"
            % (path, len(ctx["objmap"]), ctx["pages"], 1, ctx["version_minor"]))
        ctxs.append(ctx)

    total_pages = sum(c["pages"] for c in ctxs)
    log("[stage] building merged output")
    result = build_output(ctxs, total_pages)
    with open(TMP_FILE, "wb") as fh:
        fh.write(result)
    os.replace(TMP_FILE, OUTPUT_FILE)

    log("[stage] validating merged output")
    with open(OUTPUT_FILE, "rb") as fh:
        check_data = fh.read()
    check_ctx = parse_pdf(check_data)
    check_pages = count_pages_ctx(check_ctx, check_ctx["root"])
    assert check_pages == total_pages, (
        "validation failed: merged page count %d != expected %d" % (check_pages, total_pages))
    log("Created %s (%d bytes) with %d page(s); validation passed."
        % (OUTPUT_FILE, len(result), check_pages))
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as exc:  # noqa: BLE001 - report and exit cleanly
        if os.path.exists(TMP_FILE):
            os.remove(TMP_FILE)
        print("ERROR: %s" % exc, file=sys.stderr)
        sys.exit(1)

#!/usr/bin/env python3
"""Merge report_part1.pdf and report_part2.pdf (in that order) into combined_report.pdf.

Pure standard-library PDF merger. Handles:
  - classic xref tables and xref streams (with /Prev chains)
  - object streams (/ObjStm) via FlateDecode (+ PNG predictors)
  - indirect /Length resolution
Strategy: copy every live object from both inputs with renumbered IDs, expand
object-stream members to classic objects, reparent the two page-tree roots under
a new root /Pages, and emit a fresh classic xref + trailer. The output is then
re-parsed to validate page count and structure.
"""
import os
import re
import sys
import zlib

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"
TMP_FILE = OUTPUT_FILE + ".tmp"


class ParseError(Exception):
    pass


# ---------------------------------------------------------------- low-level PDF tokenizing

def skip_ws_comments(data, pos):
    n = len(data)
    while pos < n:
        c = data[pos]
        if c in b"\x00\t\n\f\r ":
            pos += 1
        elif c == ord("%"):
            j = data.find(b"\n", pos)
            pos = n if j == -1 else j + 1
        else:
            break
    return pos


def scan_literal_string(data, pos):
    i = pos + 1
    depth = 1
    n = len(data)
    while i < n:
        c = data[i]
        if c == ord("\\"):
            i = min(i + 2, n)
            continue
        if c == ord("("):
            depth += 1
        elif c == ord(")"):
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    return n


def scan_hex_string(data, pos):
    i = data.find(b">", pos + 1)
    return len(data) if i == -1 else i + 1


def scan_name(data, pos):
    i = pos + 1
    n = len(data)
    while i < n and data[i] not in b"\x00\t\n\f\r ()<>[]{}/%":
        i += 1
    return i


def scan_primitive(data, pos):
    m = re.match(rb"\d+\s+\d+\s+R(?![A-Za-z0-9/])", data[pos:pos + 64])
    if m:
        return pos + m.end()
    m = re.match(rb"[+-]?(?:\d+\.?\d*|\.\d+)", data[pos:pos + 64])
    if m:
        return pos + m.end()
    i = pos
    n = len(data)
    while i < n and data[i] not in b"\x00\t\n\f\r ()<>[]{}/%":
        i += 1
    return max(i, pos + 1)


def scan_object(data, pos):
    """Return the position just after one complete PDF object starting at pos."""
    pos = skip_ws_comments(data, pos)
    if pos >= len(data):
        return pos
    c = data[pos]
    if c == ord("("):
        return scan_literal_string(data, pos)
    if c == ord("<"):
        if data[pos + 1:pos + 2] == b"<":
            pos += 2
            while True:
                pos = skip_ws_comments(data, pos)
                if pos >= len(data):
                    return pos
                if data[pos:pos + 2] == b">>":
                    return pos + 2
                c2 = data[pos]
                if c2 == ord("("):
                    pos = scan_literal_string(data, pos)
                elif c2 == ord("<"):
                    pos = scan_object(data, pos)
                elif c2 == ord("["):
                    pos = scan_object(data, pos)
                elif c2 == ord("]"):
                    pos += 1
                elif c2 == ord(">"):
                    pos += 1
                else:
                    pos = scan_primitive(data, pos)
        else:
            return scan_hex_string(data, pos)
    if c == ord("["):
        pos += 1
        while True:
            pos = skip_ws_comments(data, pos)
            if pos >= len(data):
                return pos
            if data[pos] == ord("]"):
                return pos + 1
            pos = scan_object(data, pos)
    if c == ord("/"):
        return scan_name(data, pos)
    if c in b")]>}":
        return pos + 1
    return scan_primitive(data, pos)


def parse_dict_bytes(db):
    """Parse '<< ... >>' bytes into a list of (key, value_bytes) pairs."""
    pairs = []
    pos = skip_ws_comments(db, 0)
    if db[pos:pos + 2] != b"<<":
        return pairs
    pos += 2
    while True:
        pos = skip_ws_comments(db, pos)
        if pos >= len(db) or db[pos:pos + 2] == b">>":
            break
        if db[pos] == ord("/"):
            key_end = scan_name(db, pos)
            key = db[pos + 1:key_end]
            vpos = skip_ws_comments(db, key_end)
            vend = scan_object(db, vpos)
            if vend <= vpos:
                raise ParseError("no progress while parsing dict value")
            pairs.append((key, db[vpos:vend]))
            pos = vend
        else:
            newpos = scan_object(db, pos)
            if newpos <= pos:
                raise ParseError("no progress while parsing dict")
            pos = newpos
    return pairs


def dict_get(pairs, key):
    for k, v in pairs:
        if k == key:
            return v
    return None


def ref_of(value):
    if value is None:
        return None
    m = re.match(rb"(\d+)\s+(\d+)\s+R", value.strip())
    return (int(m.group(1)), int(m.group(2))) if m else None


def int_of(value):
    if value is None:
        return None
    m = re.match(rb"(\d+)", value.strip())
    return int(m.group(1)) if m else None


def name_of(value):
    if value is None:
        return None
    value = value.strip()
    return value if value.startswith(b"/") else None


def ints_of(value):
    return [int(x) for x in re.findall(rb"\d+", value or b"")]


# ---------------------------------------------------------------- compression helpers

def inflate(data_bytes):
    try:
        return zlib.decompress(data_bytes)
    except zlib.error:
        return zlib.decompress(data_bytes, -15)


def png_unpredict(data, columns, colors, bpc):
    bpp = max(1, (colors * bpc + 7) // 8)
    rowlen = max(1, (columns * colors * bpc + 7) // 8)
    out = bytearray()
    prev = bytearray(rowlen)
    i = 0
    n = len(data)
    while i < n:
        f = data[i]
        i += 1
        row = bytearray(data[i:i + rowlen])
        i += rowlen
        if len(row) < rowlen:
            row += b"\x00" * (rowlen - len(row))
        if f == 1:
            for j in range(bpp, rowlen):
                row[j] = (row[j] + row[j - bpp]) & 0xFF
        elif f == 2:
            for j in range(rowlen):
                row[j] = (row[j] + prev[j]) & 0xFF
        elif f == 3:
            for j in range(rowlen):
                a = row[j - bpp] if j >= bpp else 0
                row[j] = (row[j] + ((a + prev[j]) >> 1)) & 0xFF
        elif f == 4:
            for j in range(rowlen):
                a = row[j - bpp] if j >= bpp else 0
                b = prev[j]
                c = prev[j - bpp] if j >= bpp else 0
                p = a + b - c
                pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
                pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                row[j] = (row[j] + pr) & 0xFF
        out += row
        prev = row
    return bytes(out)


def decode_stream_data(stream_bytes, pairs):
    filt = dict_get(pairs, b"Filter")
    if filt is not None and filt not in (b"FlateDecode", b"[FlateDecode]"):
        if not (filt.startswith(b"[") and b"FlateDecode" in filt):
            raise ParseError("unsupported stream filter: %r" % filt)
    raw = inflate(stream_bytes)
    dp = dict_get(pairs, b"DecodeParms")
    if dp and dp.startswith(b"<<"):
        dpp = parse_dict_bytes(dp)
        pred = int_of(dict_get(dpp, b"Predictor")) or 1
        if pred >= 10:
            columns = int_of(dict_get(dpp, b"Columns")) or 1
            colors = int_of(dict_get(dpp, b"Colors")) or 1
            bpc = int_of(dict_get(dpp, b"BitsPerComponent")) or 8
            raw = png_unpredict(raw, columns, colors, bpc)
    return raw


# ---------------------------------------------------------------- object access

def read_stream(data, dict_bytes, stream_pos, ctx):
    """Return stream data bytes for an object whose 'stream' keyword is at stream_pos."""
    eol = stream_pos + 6
    if data[eol:eol + 2] == b"\r\n":
        eol += 2
    elif eol < len(data) and data[eol] in (10, 13):
        eol += 1
    pairs = parse_dict_bytes(dict_bytes)
    len_val = dict_get(pairs, b"Length")
    length = None
    if len_val is not None:
        r = ref_of(len_val)
        if r:
            if ctx is not None:
                try:
                    c = ctx_get_content(ctx, r[0])
                    length = int_of(c["dict"].strip())
                except Exception:
                    length = None
        else:
            length = int_of(len_val)
    if length is not None:
        stream_bytes = data[eol:eol + length]
        after = skip_ws_comments(data, eol + length)
        if data[after:after + 9] == b"endstream":
            return stream_bytes
    idx = data.find(b"endstream", eol)
    if idx == -1:
        raise ParseError("endstream not found")
    sb = data[eol:idx]
    while sb.endswith((b"\n", b"\r")):
        sb = sb[:-1]
    return sb


def extract_type1(ctx, objnum, offset):
    data = ctx["data"]
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[offset:offset + 64])
    if not m or int(m.group(1)) != objnum:
        raise ParseError("object %d not found at offset %d" % (objnum, offset))
    bs = offset + m.end()
    bs = skip_ws_comments(data, bs)
    if data[bs:bs + 2] == b"<<":
        dict_end = scan_object(data, bs)
        dict_bytes = data[bs:dict_end]
        sk = skip_ws_comments(data, dict_end)
        if data[sk:sk + 6] == b"stream":
            return {"kind": "stream", "dict": dict_bytes,
                    "stream": read_stream(data, dict_bytes, sk, ctx)}
        eo = data.find(b"endobj", dict_end)
        if eo == -1:
            raise ParseError("endobj not found for object %d" % objnum)
        return {"kind": "dict", "dict": data[bs:eo].rstrip(b"\x00\t\n\f\r ")}
    eo = data.find(b"endobj", bs)
    if eo == -1:
        raise ParseError("endobj not found for object %d" % objnum)
    return {"kind": "dict", "dict": data[bs:eo].rstrip(b"\x00\t\n\f\r ")}


def ctx_get_content(ctx, num):
    cache = ctx["cache"]
    if num in cache:
        return cache[num]
    entry = ctx["objmap"].get(num)
    if entry is None:
        raise ParseError("object %d not present in xref" % num)
    if entry[0] == "direct":
        content = extract_type1(ctx, num, entry[1])
    else:
        stmnum, idx = entry[1], entry[2]
        ctx["skipped"].add(stmnum)
        stm = ctx_get_content(ctx, stmnum)
        if stm["kind"] != "stream":
            raise ParseError("object stream %d is not a stream" % stmnum)
        pairs = parse_dict_bytes(stm["dict"])
        n = int_of(dict_get(pairs, b"N")) or 0
        first = int_of(dict_get(pairs, b"First")) or 0
        raw = decode_stream_data(stm["stream"], pairs)
        toks = re.findall(rb"\d+", raw[:first])
        offs = [int(toks[i + 1]) for i in range(0, min(2 * n, len(toks) - 1), 2)]
        if idx >= len(offs):
            raise ParseError("object stream index out of range (obj %d)" % num)
        start = first + offs[idx]
        end = scan_object(raw, start)
        content = {"kind": "dict", "dict": raw[start:end].strip()}
    cache[num] = content
    return content


# ---------------------------------------------------------------- xref parsing

def parse_classic_xref(data, pos):
    objmap = {}
    p = data.find(b"xref", pos)
    if p == -1:
        raise ParseError("classic xref not found at %d" % pos)
    p += 4
    while True:
        prev_p = p
        p = skip_ws_comments(data, p)
        if data[p:p + 7] == b"trailer":
            break
        m = re.match(rb"(\d+)\s+(\d+)\s+", data[p:p + 64])
        if not m:
            break
        start = int(m.group(1))
        count = int(m.group(2))
        p += m.end()
        for _ in range(count):
            p = skip_ws_comments(data, p)
            m2 = re.match(rb"(\d+)\s+(\d+)\s+([nf])", data[p:p + 64])
            if not m2:
                raise ParseError("bad xref entry near %d" % p)
            offset = int(m2.group(1))
            typ = m2.group(3)
            if typ == b"n" and offset > 0:
                objmap[start] = ("direct", offset)
            start += 1
            p += m2.end()
        if p == prev_p:
            raise ParseError("no progress while parsing classic xref")
    t = data.find(b"trailer", p)
    if t == -1:
        raise ParseError("trailer keyword not found")
    ts = data.find(b"<<", t)
    te = data.find(b">>", ts)
    trailer_raw = data[ts:te + 2]
    return objmap, parse_dict_bytes(trailer_raw)


def parse_xref_stream(data, pos):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[pos:pos + 64])
    if not m:
        raise ParseError("xref stream object header not found at %d" % pos)
    xref_objnum = int(m.group(1))
    body_start = pos + m.end()
    bs = skip_ws_comments(data, body_start)
    dict_end = scan_object(data, bs)
    dict_bytes = data[bs:dict_end]
    pairs = parse_dict_bytes(dict_bytes)
    sk = skip_ws_comments(data, dict_end)
    stream_bytes = read_stream(data, dict_bytes, sk, None)
    raw = decode_stream_data(stream_bytes, pairs)
    w = ints_of(dict_get(pairs, b"W")) or [1, 4, 2]
    if len(w) < 2:
        w = [1, 4, 2]
    size = int_of(dict_get(pairs, b"Size")) or 0
    idx_vals = ints_of(dict_get(pairs, b"Index")) or [0, size]
    prev = int_of(dict_get(pairs, b"Prev"))
    elen = sum(w)
    objmap = {}
    p = 0
    for k in range(0, len(idx_vals), 2):
        start = idx_vals[k]
        cnt = idx_vals[k + 1] if k + 1 < len(idx_vals) else 0
        for i in range(cnt):
            if p + elen > len(raw):
                break
            entry = raw[p:p + elen]
            p += elen
            t = 1 if w[0] == 0 else int.from_bytes(entry[:w[0]], "big")
            f2 = 0 if w[1] == 0 else int.from_bytes(entry[w[0]:w[0] + w[1]], "big")
            f3 = 0
            if len(w) > 2 and w[2] > 0:
                f3 = int.from_bytes(entry[w[0] + w[1]:w[0] + w[1] + w[2]], "big")
            onum = start + i
            if t == 1:
                objmap[onum] = ("direct", f2)
            elif t == 2:
                objmap[onum] = ("objstm", f2, f3)
    return objmap, pairs, prev, xref_objnum


def parse_pdf(data):
    m = re.match(rb"%PDF-(\d)\.(\d)", data[:64])
    version_minor = int(m.group(2)) if m else 4
    sms = list(re.finditer(rb"startxref\s+(\d+)", data))
    if not sms:
        raise ParseError("no startxref found")
    xref_pos = int(sms[-1].group(1))
    objmap = {}
    trailer_pairs = None
    skipped = set()
    pos = xref_pos
    seen = set()
    while pos and pos not in seen:
        seen.add(pos)
        if data[pos:pos + 4] == b"xref":
            m2, tp = parse_classic_xref(data, pos)
            prev = int_of(dict_get(tp, b"Prev"))
        else:
            m2, tp, prev, xnum = parse_xref_stream(data, pos)
            skipped.add(xnum)
        for k, v in m2.items():
            if k not in objmap:
                objmap[k] = v
        if trailer_pairs is None:
            trailer_pairs = tp
        pos = prev
    if dict_get(trailer_pairs, b"Encrypt") is not None:
        raise ParseError("encrypted PDFs are not supported")
    root_ref = ref_of(dict_get(trailer_pairs, b"Root"))
    if not root_ref:
        raise ParseError("no /Root in trailer")
    ctx = {"data": data, "objmap": objmap, "trailer": trailer_pairs,
           "version_minor": version_minor, "cache": {}, "skipped": skipped}
    catalog = ctx_get_content(ctx, root_ref[0])
    cpairs = parse_dict_bytes(catalog["dict"])
    pages_ref = ref_of(dict_get(cpairs, b"Pages"))
    if not pages_ref:
        raise ParseError("no /Pages in catalog")
    ctx["root"] = pages_ref[0]
    return ctx


# ---------------------------------------------------------------- page tree walking

def refs_from_value(ctx, value):
    if value is None:
        return []
    r = ref_of(value)
    if r:
        body = ctx_get_content(ctx, r[0])["dict"].strip()
        if body.startswith(b"["):
            return [int(x.group(1)) for x in re.finditer(rb"(\d+)\s+\d+\s+R", body)]
        return [r[0]]
    return [int(x.group(1)) for x in re.finditer(rb"(\d+)\s+\d+\s+R", value)]


def count_pages_ctx(ctx, node_num, depth=0):
    if depth > 100000:
        raise ParseError("page tree too deep (possible cycle)")
    content = ctx_get_content(ctx, node_num)
    pairs = parse_dict_bytes(content["dict"])
    typ = name_of(dict_get(pairs, b"Type"))
    if typ == b"Page":
        return 1
    kids = refs_from_value(ctx, dict_get(pairs, b"Kids"))
    return sum(count_pages_ctx(ctx, k, depth + 1) for k in kids)


# ---------------------------------------------------------------- serialization helpers

def rewrite_refs(data, mapping):
    """Copy bytes verbatim, replacing 'old 0 R' references outside strings/comments."""
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        c = data[i]
        if c == ord("%"):
            j = data.find(b"\n", i)
            j = n if j == -1 else j
            out += data[i:j]
            i = j
        elif c == ord("("):
            j = scan_literal_string(data, i)
            out += data[i:j]
            i = j
        elif c == ord("<"):
            if data[i + 1:i + 2] == b"<":
                out += data[i:i + 1]
                i += 1
            else:
                j = scan_hex_string(data, i)
                out += data[i:j]
                i = j
        elif c == ord(">") or c == ord("/") or c in b"[]":
            out += data[i:i + 1]
            i += 1
        elif c in b"0123456789+-.":
            m = re.match(rb"(\d+)\s+(\d+)\s+R(?![A-Za-z0-9/])", data[i:i + 64])
            if m and int(m.group(1)) in mapping:
                out += b"%d %d R" % (mapping[int(m.group(1))], int(m.group(2)))
                i += m.end()
                continue
            m2 = re.match(rb"[+-]?(?:\d+\.?\d*|\.\d+)", data[i:i + 64])
            if m2:
                out += data[i:i + m2.end()]
                i += m2.end()
                continue
            out += data[i:i + 1]
            i += 1
        else:
            out += data[i:i + 1]
            i += 1
    return bytes(out)


def set_length(dict_bytes, length):
    m = re.search(rb"/Length\s+(\d+)(?:\s+\d+\s+R)?", dict_bytes)
    repl = b"/Length " + str(length).encode()
    if m:
        return dict_bytes[:m.start()] + repl + dict_bytes[m.end():]
    idx = dict_bytes.rfind(b">>")
    return dict_bytes[:idx] + repl + b" " + dict_bytes[idx:]


def patch_parent(dict_bytes, newroot):
    m = re.search(rb"/Parent\s+\d+\s+\d+\s+R", dict_bytes)
    repl = b"/Parent " + str(newroot).encode() + b" 0 R"
    if m:
        return dict_bytes[:m.start()] + repl + dict_bytes[m.end():]
    idx = dict_bytes.rfind(b">>")
    return dict_bytes[:idx] + repl + b" " + dict_bytes[idx:]


# ---------------------------------------------------------------- merge

def build_output(ctxs, total_pages):
    roots = [ctx["root"] for ctx in ctxs]
    entries = []
    for ctx in ctxs:
        for oldnum in sorted(ctx["objmap"]):
            if oldnum in ctx["skipped"]:
                continue
            content = ctx_get_content(ctx, oldnum)
            if oldnum in ctx["skipped"]:
                continue
            entries.append((ctx, oldnum, content))
    mapping = {}
    for i, (_, oldnum, _) in enumerate(entries, start=1):
        mapping[oldnum] = i
    catalog_num = len(entries) + 1
    pages_num = len(entries) + 2

    out = bytearray()
    minor = max(ctx["version_minor"] for ctx in ctxs)
    out += b"%%PDF-1.%d\n" % max(4, minor)
    xref_offsets = {}
    for i, (ctx, oldnum, content) in enumerate(entries, start=1):
        xref_offsets[i] = len(out)
        body = rewrite_refs(content["dict"], mapping)
        if oldnum in roots:
            body = patch_parent(body, pages_num)
        if content["kind"] == "stream":
            sb = content["stream"]
            body = set_length(body, len(sb))
            out += b"%d 0 obj\n" % i + body + b"\nstream\n" + sb + b"\nendstream\nendobj\n"
        else:
            out += b"%d 0 obj\n" % i + body + b"\nendobj\n"
    xref_offsets[catalog_num] = len(out)
    out += (b"%d 0 obj\n<< /Type /Catalog /Pages %d 0 R >>\nendobj\n"
            % (catalog_num, pages_num))
    xref_offsets[pages_num] = len(out)
    kids = b" ".join(b"%d 0 R" % mapping[root] for root in roots)
    out += (b"%d 0 obj\n<< /Type /Pages /Kids [%s] /Count %d >>\nendobj\n"
            % (pages_num, kids, total_pages))
    xref_pos = len(out)
    count = pages_num + 1
    out += b"xref\n0 %d\n" % count
    out += b"0000000000 65535 f \n"
    for i in range(1, count):
        out += b"%010d 00000 n \n" % xref_offsets[i]
    trailer = b"<< /Size %d /Root %d 0 R" % (count, catalog_num)
    info_ref = ref_of(dict_get(ctxs[0]["trailer"], b"Info"))
    if info_ref and info_ref[0] in mapping:
        trailer += b" /Info %d 0 R" % mapping[info_ref[0]]
    trailer += b" >>"
    out += b"trailer\n" + trailer + b"\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    return bytes(out)


def main():
    ctxs = []
    for path in INPUT_FILES:
        with open(path, "rb") as fh:
            data = fh.read()
        if not data.startswith(b"%PDF-"):
            raise ParseError("%s is not a PDF file" % path)
        ctx = parse_pdf(data)
        ctx["pages"] = count_pages_ctx(ctx, ctx["root"])
        print("Parsed %s: %d objects, %d page(s), PDF-%d.%d"
              % (path, len(ctx["objmap"]), ctx["pages"], 1, ctx["version_minor"]),
              flush=True)
        ctxs.append(ctx)

    total_pages = sum(c["pages"] for c in ctxs)
    result = build_output(ctxs, total_pages)
    with open(TMP_FILE, "wb") as fh:
        fh.write(result)
    os.replace(TMP_FILE, OUTPUT_FILE)

    with open(OUTPUT_FILE, "rb") as fh:
        check_data = fh.read()
    check_ctx = parse_pdf(check_data)
    check_pages = count_pages_ctx(check_ctx, check_ctx["root"])
    assert check_pages == total_pages, (
        "validation failed: merged page count %d != expected %d" % (check_pages, total_pages))
    print("Created %s (%d bytes) with %d page(s); validation passed."
          % (OUTPUT_FILE, len(result), check_pages), flush=True)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as exc:  # noqa: BLE001 - report and exit cleanly
        if os.path.exists(TMP_FILE):
            os.remove(TMP_FILE)
        print("ERROR: %s" % exc, file=sys.stderr)
        sys.exit(1)

#!/usr/bin/env python3
"""Merge report_part1.pdf and report_part2.pdf (in that order) into combined_report.pdf.

Pure standard-library PDF merger. Handles:
  - classic xref tables and xref streams (with /Prev chains)
  - object streams (/ObjStm) via FlateDecode (+ PNG predictors)
  - indirect /Length resolution
Strategy: copy every live object from both inputs with renumbered IDs, expand
object-stream members to classic objects, reparent the two page-tree roots under
a new root /Pages, and emit a fresh classic xref + trailer. The output is then
re-parsed to validate page count and structure.
"""
import os
import re
import sys
import zlib

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"
TMP_FILE = OUTPUT_FILE + ".tmp"


class ParseError(Exception):
    pass


# ---------------------------------------------------------------- low-level PDF tokenizing

def skip_ws_comments(data, pos):
    n = len(data)
    while pos < n:
        c = data[pos]
        if c in b"\x00\t\n\f\r ":
            pos += 1
        elif c == ord("%"):
            j = data.find(b"\n", pos)
            pos = n if j == -1 else j + 1
        else:
            break
    return pos


def scan_literal_string(data, pos):
    i = pos + 1
    depth = 1
    n = len(data)
    while i < n:
        c = data[i]
        if c == ord("\\"):
            i = min(i + 2, n)
            continue
        if c == ord("("):
            depth += 1
        elif c == ord(")"):
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    return n


def scan_hex_string(data, pos):
    i = data.find(b">", pos + 1)
    return len(data) if i == -1 else i + 1


def scan_name(data, pos):
    i = pos + 1
    n = len(data)
    while i < n and data[i] not in b"\x00\t\n\f\r ()<>[]{}/%":
        i += 1
    return i


def scan_primitive(data, pos):
    m = re.match(rb"\d+\s+\d+\s+R(?![A-Za-z0-9/])", data[pos:pos + 64])
    if m:
        return pos + m.end()
    m = re.match(rb"[+-]?(?:\d+\.?\d*|\.\d+)", data[pos:pos + 64])
    if m:
        return pos + m.end()
    i = pos
    n = len(data)
    while i < n and data[i] not in b"\x00\t\n\f\r ()<>[]{}/%":
        i += 1
    return max(i, pos + 1)


def scan_object(data, pos):
    """Return the position just after one complete PDF object starting at pos."""
    pos = skip_ws_comments(data, pos)
    if pos >= len(data):
        return pos
    c = data[pos]
    if c == ord("("):
        return scan_literal_string(data, pos)
    if c == ord("<"):
        if data[pos + 1:pos + 2] == b"<":
            pos += 2
            while True:
                pos = skip_ws_comments(data, pos)
                if pos >= len(data):
                    return pos
                if data[pos:pos + 2] == b">>":
                    return pos + 2
                c2 = data[pos]
                if c2 == ord("("):
                    pos = scan_literal_string(data, pos)
                elif c2 == ord("<"):
                    pos = scan_object(data, pos)
                elif c2 == ord("["):
                    pos = scan_object(data, pos)
                elif c2 == ord("]"):
                    pos += 1
                elif c2 == ord(">"):
                    pos += 1
                else:
                    pos = scan_primitive(data, pos)
        else:
            return scan_hex_string(data, pos)
    if c == ord("["):
        pos += 1
        while True:
            pos = skip_ws_comments(data, pos)
            if pos >= len(data):
                return pos
            if data[pos] == ord("]"):
                return pos + 1
            pos = scan_object(data, pos)
    if c == ord("/"):
        return scan_name(data, pos)
    if c in b")]>}":
        return pos + 1
    return scan_primitive(data, pos)


def parse_dict_bytes(db):
    """Parse '<< ... >>' bytes into a list of (key, value_bytes) pairs."""
    pairs = []
    pos = skip_ws_comments(db, 0)
    if db[pos:pos + 2] != b"<<":
        return pairs
    pos += 2
    while True:
        pos = skip_ws_comments(db, pos)
        if pos >= len(db) or db[pos:pos + 2] == b">>":
            break
        if db[pos] == ord("/"):
            key_end = scan_name(db, pos)
            key = db[pos + 1:key_end]
            vpos = skip_ws_comments(db, key_end)
            vend = scan_object(db, vpos)
            if vend <= vpos:
                raise ParseError("no progress while parsing dict value")
            pairs.append((key, db[vpos:vend]))
            pos = vend
        else:
            newpos = scan_object(db, pos)
            if newpos <= pos:
                raise ParseError("no progress while parsing dict")
            pos = newpos
    return pairs


def dict_get(pairs, key):
    for k, v in pairs:
        if k == key:
            return v
    return None


def ref_of(value):
    if value is None:
        return None
    m = re.match(rb"(\d+)\s+(\d+)\s+R", value.strip())
    return (int(m.group(1)), int(m.group(2))) if m else None


def int_of(value):
    if value is None:
        return None
    m = re.match(rb"(\d+)", value.strip())
    return int(m.group(1)) if m else None


def name_of(value):
    if value is None:
        return None
    value = value.strip()
    return value if value.startswith(b"/") else None


def ints_of(value):
    return [int(x) for x in re.findall(rb"\d+", value or b"")]


# ---------------------------------------------------------------- compression helpers

def inflate(data_bytes):
    try:
        return zlib.decompress(data_bytes)
    except zlib.error:
        return zlib.decompress(data_bytes, -15)


def png_unpredict(data, columns, colors, bpc):
    bpp = max(1, (colors * bpc + 7) // 8)
    rowlen = max(1, (columns * colors * bpc + 7) // 8)
    out = bytearray()
    prev = bytearray(rowlen)
    i = 0
    n = len(data)
    while i < n:
        f = data[i]
        i += 1
        row = bytearray(data[i:i + rowlen])
        i += rowlen
        if len(row) < rowlen:
            row += b"\x00" * (rowlen - len(row))
        if f == 1:
            for j in range(bpp, rowlen):
                row[j] = (row[j] + row[j - bpp]) & 0xFF
        elif f == 2:
            for j in range(rowlen):
                row[j] = (row[j] + prev[j]) & 0xFF
        elif f == 3:
            for j in range(rowlen):
                a = row[j - bpp] if j >= bpp else 0
                row[j] = (row[j] + ((a + prev[j]) >> 1)) & 0xFF
        elif f == 4:
            for j in range(rowlen):
                a = row[j - bpp] if j >= bpp else 0
                b = prev[j]
                c = prev[j - bpp] if j >= bpp else 0
                p = a + b - c
                pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
                pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                row[j] = (row[j] + pr) & 0xFF
        out += row
        prev = row
    return bytes(out)


def decode_stream_data(stream_bytes, pairs):
    filt = dict_get(pairs, b"Filter")
    if filt is not None and filt not in (b"FlateDecode", b"[FlateDecode]"):
        if not (filt.startswith(b"[") and b"FlateDecode" in filt):
            raise ParseError("unsupported stream filter: %r" % filt)
    raw = inflate(stream_bytes)
    dp = dict_get(pairs, b"DecodeParms")
    if dp and dp.startswith(b"<<"):
        dpp = parse_dict_bytes(dp)
        pred = int_of(dict_get(dpp, b"Predictor")) or 1
        if pred >= 10:
            columns = int_of(dict_get(dpp, b"Columns")) or 1
            colors = int_of(dict_get(dpp, b"Colors")) or 1
            bpc = int_of(dict_get(dpp, b"BitsPerComponent")) or 8
            raw = png_unpredict(raw, columns, colors, bpc)
    return raw


# ---------------------------------------------------------------- object access

def read_stream(data, dict_bytes, stream_pos, ctx):
    """Return stream data bytes for an object whose 'stream' keyword is at stream_pos."""
    eol = stream_pos + 6
    if data[eol:eol + 2] == b"\r\n":
        eol += 2
    elif eol < len(data) and data[eol] in (10, 13):
        eol += 1
    pairs = parse_dict_bytes(dict_bytes)
    len_val = dict_get(pairs, b"Length")
    length = None
    if len_val is not None:
        r = ref_of(len_val)
        if r:
            if ctx is not None:
                try:
                    c = ctx_get_content(ctx, r[0])
                    length = int_of(c["dict"].strip())
                except Exception:
                    length = None
        else:
            length = int_of(len_val)
    if length is not None:
        stream_bytes = data[eol:eol + length]
        after = skip_ws_comments(data, eol + length)
        if data[after:after + 9] == b"endstream":
            return stream_bytes
    idx = data.find(b"endstream", eol)
    if idx == -1:
        raise ParseError("endstream not found")
    sb = data[eol:idx]
    while sb.endswith((b"\n", b"\r")):
        sb = sb[:-1]
    return sb


def extract_type1(ctx, objnum, offset):
    data = ctx["data"]
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[offset:offset + 64])
    if not m or int(m.group(1)) != objnum:
        raise ParseError("object %d not found at offset %d" % (objnum, offset))
    bs = offset + m.end()
    bs = skip_ws_comments(data, bs)
    if data[bs:bs + 2] == b"<<":
        dict_end = scan_object(data, bs)
        dict_bytes = data[bs:dict_end]
        sk = skip_ws_comments(data, dict_end)
        if data[sk:sk + 6] == b"stream":
            return {"kind": "stream", "dict": dict_bytes,
                    "stream": read_stream(data, dict_bytes, sk, ctx)}
        eo = data.find(b"endobj", dict_end)
        if eo == -1:
            raise ParseError("endobj not found for object %d" % objnum)
        return {"kind": "dict", "dict": data[bs:eo].rstrip(b"\x00\t\n\f\r ")}
    eo = data.find(b"endobj", bs)
    if eo == -1:
        raise ParseError("endobj not found for object %d" % objnum)
    return {"kind": "dict", "dict": data[bs:eo].rstrip(b"\x00\t\n\f\r ")}


def ctx_get_content(ctx, num):
    cache = ctx["cache"]
    if num in cache:
        return cache[num]
    entry = ctx["objmap"].get(num)
    if entry is None:
        raise ParseError("object %d not present in xref" % num)
    if entry[0] == "direct":
        content = extract_type1(ctx, num, entry[1])
    else:
        stmnum, idx = entry[1], entry[2]
        ctx["skipped"].add(stmnum)
        stm = ctx_get_content(ctx, stmnum)
        if stm["kind"] != "stream":
            raise ParseError("object stream %d is not a stream" % stmnum)
        pairs = parse_dict_bytes(stm["dict"])
        n = int_of(dict_get(pairs, b"N")) or 0
        first = int_of(dict_get(pairs, b"First")) or 0
        raw = decode_stream_data(stm["stream"], pairs)
        toks = re.findall(rb"\d+", raw[:first])
        offs = [int(toks[i + 1]) for i in range(0, min(2 * n, len(toks) - 1), 2)]
        if idx >= len(offs):
            raise ParseError("object stream index out of range (obj %d)" % num)
        start = first + offs[idx]
        end = scan_object(raw, start)
        content = {"kind": "dict", "dict": raw[start:end].strip()}
    cache[num] = content
    return content


# ---------------------------------------------------------------- xref parsing

def parse_classic_xref(data, pos):
    objmap = {}
    p = data.find(b"xref", pos)
    if p == -1:
        raise ParseError("classic xref not found at %d" % pos)
    p += 4
    while True:
        prev_p = p
        p = skip_ws_comments(data, p)
        if data[p:p + 7] == b"trailer":
            break
        m = re.match(rb"(\d+)\s+(\d+)\s+", data[p:p + 64])
        if not m:
            break
        start = int(m.group(1))
        count = int(m.group(2))
        p += m.end()
        for _ in range(count):
            p = skip_ws_comments(data, p)
            m2 = re.match(rb"(\d+)\s+(\d+)\s+([nf])", data[p:p + 64])
            if not m2:
                raise ParseError("bad xref entry near %d" % p)
            offset = int(m2.group(1))
            typ = m2.group(3)
            if typ == b"n" and offset > 0:
                objmap[start] = ("direct", offset)
            start += 1
            p += m2.end()
        if p == prev_p:
            raise ParseError("no progress while parsing classic xref")
    t = data.find(b"trailer", p)
    if t == -1:
        raise ParseError("trailer keyword not found")
    ts = data.find(b"<<", t)
    te = data.find(b">>", ts)
    trailer_raw = data[ts:te + 2]
    return objmap, parse_dict_bytes(trailer_raw)


def parse_xref_stream(data, pos):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[pos:pos + 64])
    if not m:
        raise ParseError("xref stream object header not found at %d" % pos)
    xref_objnum = int(m.group(1))
    body_start = pos + m.end()
    bs = skip_ws_comments(data, body_start)
    dict_end = scan_object(data, bs)
    dict_bytes = data[bs:dict_end]
    pairs = parse_dict_bytes(dict_bytes)
    sk = skip_ws_comments(data, dict_end)
    stream_bytes = read_stream(data, dict_bytes, sk, None)
    raw = decode_stream_data(stream_bytes, pairs)
    w = ints_of(dict_get(pairs, b"W")) or [1, 4, 2]
    if len(w) < 2:
        w = [1, 4, 2]
    size = int_of(dict_get(pairs, b"Size")) or 0
    idx_vals = ints_of(dict_get(pairs, b"Index")) or [0, size]
    prev = int_of(dict_get(pairs, b"Prev"))
    elen = sum(w)
    objmap = {}
    p = 0
    for k in range(0, len(idx_vals), 2):
        start = idx_vals[k]
        cnt = idx_vals[k + 1] if k + 1 < len(idx_vals) else 0
        for i in range(cnt):
            if p + elen > len(raw):
                break
            entry = raw[p:p + elen]
            p += elen
            t = 1 if w[0] == 0 else int.from_bytes(entry[:w[0]], "big")
            f2 = 0 if w[1] == 0 else int.from_bytes(entry[w[0]:w[0] + w[1]], "big")
            f3 = 0
            if len(w) > 2 and w[2] > 0:
                f3 = int.from_bytes(entry[w[0] + w[1]:w[0] + w[1] + w[2]], "big")
            onum = start + i
            if t == 1:
                objmap[onum] = ("direct", f2)
            elif t == 2:
                objmap[onum] = ("objstm", f2, f3)
    return objmap, pairs, prev, xref_objnum


def parse_pdf(data):
    m = re.match(rb"%PDF-(\d)\.(\d)", data[:64])
    version_minor = int(m.group(2)) if m else 4
    sms = list(re.finditer(rb"startxref\s+(\d+)", data))
    if not sms:
        raise ParseError("no startxref found")
    xref_pos = int(sms[-1].group(1))
    objmap = {}
    trailer_pairs = None
    skipped = set()
    pos = xref_pos
    seen = set()
    while pos and pos not in seen:
        seen.add(pos)
        if data[pos:pos + 4] == b"xref":
            m2, tp = parse_classic_xref(data, pos)
            prev = int_of(dict_get(tp, b"Prev"))
        else:
            m2, tp, prev, xnum = parse_xref_stream(data, pos)
            skipped.add(xnum)
        for k, v in m2.items():
            if k not in objmap:
                objmap[k] = v
        if trailer_pairs is None:
            trailer_pairs = tp
        pos = prev
    if dict_get(trailer_pairs, b"Encrypt") is not None:
        raise ParseError("encrypted PDFs are not supported")
    root_ref = ref_of(dict_get(trailer_pairs, b"Root"))
    if not root_ref:
        raise ParseError("no /Root in trailer")
    ctx = {"data": data, "objmap": objmap, "trailer": trailer_pairs,
           "version_minor": version_minor, "cache": {}, "skipped": skipped}
    catalog = ctx_get_content(ctx, root_ref[0])
    cpairs = parse_dict_bytes(catalog["dict"])
    pages_ref = ref_of(dict_get(cpairs, b"Pages"))
    if not pages_ref:
        raise ParseError("no /Pages in catalog")
    ctx["root"] = pages_ref[0]
    return ctx


# ---------------------------------------------------------------- page tree walking

def refs_from_value(ctx, value):
    if value is None:
        return []
    r = ref_of(value)
    if r:
        body = ctx_get_content(ctx, r[0])["dict"].strip()
        if body.startswith(b"["):
            return [int(x.group(1)) for x in re.finditer(rb"(\d+)\s+\d+\s+R", body)]
        return [r[0]]
    return [int(x.group(1)) for x in re.finditer(rb"(\d+)\s+\d+\s+R", value)]


def count_pages_ctx(ctx, node_num, depth=0):
    if depth > 100000:
        raise ParseError("page tree too deep (possible cycle)")
    content = ctx_get_content(ctx, node_num)
    pairs = parse_dict_bytes(content["dict"])
    typ = name_of(dict_get(pairs, b"Type"))
    if typ == b"/Page":
        return 1
    kids = refs_from_value(ctx, dict_get(pairs, b"Kids"))
    return sum(count_pages_ctx(ctx, k, depth + 1) for k in kids)


# ---------------------------------------------------------------- serialization helpers

def rewrite_refs(data, mapping):
    """Copy bytes verbatim, replacing 'old 0 R' references outside strings/comments."""
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        c = data[i]
        if c == ord("%"):
            j = data.find(b"\n", i)
            j = n if j == -1 else j
            out += data[i:j]
            i = j
        elif c == ord("("):
            j = scan_literal_string(data, i)
            out += data[i:j]
            i = j
        elif c == ord("<"):
            if data[i + 1:i + 2] == b"<":
                out += data[i:i + 1]
                i += 1
            else:
                j = scan_hex_string(data, i)
                out += data[i:j]
                i = j
        elif c == ord(">") or c == ord("/") or c in b"[]":
            out += data[i:i + 1]
            i += 1
        elif c in b"0123456789+-.":
            m = re.match(rb"(\d+)\s+(\d+)\s+R(?![A-Za-z0-9/])", data[i:i + 64])
            if m and int(m.group(1)) in mapping:
                out += b"%d %d R" % (mapping[int(m.group(1))], int(m.group(2)))
                i += m.end()
                continue
            m2 = re.match(rb"[+-]?(?:\d+\.?\d*|\.\d+)", data[i:i + 64])
            if m2:
                out += data[i:i + m2.end()]
                i += m2.end()
                continue
            out += data[i:i + 1]
            i += 1
        else:
            out += data[i:i + 1]
            i += 1
    return bytes(out)


def set_length(dict_bytes, length):
    m = re.search(rb"/Length\s+(\d+)(?:\s+\d+\s+R)?", dict_bytes)
    repl = b"/Length " + str(length).encode()
    if m:
        return dict_bytes[:m.start()] + repl + dict_bytes[m.end():]
    idx = dict_bytes.rfind(b">>")
    return dict_bytes[:idx] + repl + b" " + dict_bytes[idx:]


def patch_parent(dict_bytes, newroot):
    m = re.search(rb"/Parent\s+\d+\s+\d+\s+R", dict_bytes)
    repl = b"/Parent " + str(newroot).encode() + b" 0 R"
    if m:
        return dict_bytes[:m.start()] + repl + dict_bytes[m.end():]
    idx = dict_bytes.rfind(b">>")
    return dict_bytes[:idx] + repl + b" " + dict_bytes[idx:]


# ---------------------------------------------------------------- merge

def build_output(ctxs, total_pages):
    roots = [ctx["root"] for ctx in ctxs]
    entries = []
    for ctx in ctxs:
        for oldnum in sorted(ctx["objmap"]):
            if oldnum in ctx["skipped"]:
                continue
            content = ctx_get_content(ctx, oldnum)
            if oldnum in ctx["skipped"]:
                continue
            entries.append((ctx, oldnum, content))
    mapping = {}
    for i, (_, oldnum, _) in enumerate(entries, start=1):
        mapping[oldnum] = i
    catalog_num = len(entries) + 1
    pages_num = len(entries) + 2

    out = bytearray()
    minor = max(ctx["version_minor"] for ctx in ctxs)
    out += b"%%PDF-1.%d\n" % max(4, minor)
    xref_offsets = {}
    for i, (ctx, oldnum, content) in enumerate(entries, start=1):
        xref_offsets[i] = len(out)
        body = rewrite_refs(content["dict"], mapping)
        if oldnum in roots:
            body = patch_parent(body, pages_num)
        if content["kind"] == "stream":
            sb = content["stream"]
            body = set_length(body, len(sb))
            out += b"%d 0 obj\n" % i + body + b"\nstream\n" + sb + b"\nendstream\nendobj\n"
        else:
            out += b"%d 0 obj\n" % i + body + b"\nendobj\n"
    xref_offsets[catalog_num] = len(out)
    out += (b"%d 0 obj\n<< /Type /Catalog /Pages %d 0 R >>\nendobj\n"
            % (catalog_num, pages_num))
    xref_offsets[pages_num] = len(out)
    kids = b" ".join(b"%d 0 R" % mapping[root] for root in roots)
    out += (b"%d 0 obj\n<< /Type /Pages /Kids [%s] /Count %d >>\nendobj\n"
            % (pages_num, kids, total_pages))
    xref_pos = len(out)
    count = pages_num + 1
    out += b"xref\n0 %d\n" % count
    out += b"0000000000 65535 f \n"
    for i in range(1, count):
        out += b"%010d 00000 n \n" % xref_offsets[i]
    trailer = b"<< /Size %d /Root %d 0 R" % (count, catalog_num)
    info_ref = ref_of(dict_get(ctxs[0]["trailer"], b"Info"))
    if info_ref and info_ref[0] in mapping:
        trailer += b" /Info %d 0 R" % mapping[info_ref[0]]
    trailer += b" >>"
    out += b"trailer\n" + trailer + b"\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    return bytes(out)


def main():
    ctxs = []
    for path in INPUT_FILES:
        with open(path, "rb") as fh:
            data = fh.read()
        if not data.startswith(b"%PDF-"):
            raise ParseError("%s is not a PDF file" % path)
        ctx = parse_pdf(data)
        ctx["pages"] = count_pages_ctx(ctx, ctx["root"])
        print("Parsed %s: %d objects, %d page(s), PDF-%d.%d"
              % (path, len(ctx["objmap"]), ctx["pages"], 1, ctx["version_minor"]),
              flush=True)
        ctxs.append(ctx)

    total_pages = sum(c["pages"] for c in ctxs)
    result = build_output(ctxs, total_pages)
    with open(TMP_FILE, "wb") as fh:
        fh.write(result)
    os.replace(TMP_FILE, OUTPUT_FILE)

    with open(OUTPUT_FILE, "rb") as fh:
        check_data = fh.read()
    check_ctx = parse_pdf(check_data)
    check_pages = count_pages_ctx(check_ctx, check_ctx["root"])
    assert check_pages == total_pages, (
        "validation failed: merged page count %d != expected %d" % (check_pages, total_pages))
    print("Created %s (%d bytes) with %d page(s); validation passed."
          % (OUTPUT_FILE, len(result), check_pages), flush=True)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as exc:  # noqa: BLE001 - report and exit cleanly
        if os.path.exists(TMP_FILE):
            os.remove(TMP_FILE)
        print("ERROR: %s" % exc, file=sys.stderr)
        sys.exit(1)

obligations.invalid_value:
#!/usr/bin/env python3
"""Merge report_part1.pdf and report_part2.pdf (in that order) into combined_report.pdf.

Pure standard-library PDF merger. Handles:
  - classic xref tables and xref streams (with /Prev chains)
  - object streams (/ObjStm) via FlateDecode (+ PNG predictors)
  - indirect /Length resolution
Strategy: copy every live object from both inputs with renumbered IDs, expand
object-stream members to classic objects, reparent the two page-tree roots under
a new root /Pages, and emit a fresh classic xref + trailer. The output is then
re-parsed to validate page count and structure.
"""
import os
import re
import sys
import zlib

sys.setrecursionlimit(100000)

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"
TMP_FILE = OUTPUT_FILE + ".tmp"


def log(msg):
    print(msg, flush=True)


class ParseError(Exception):
    pass


# ---------------------------------------------------------------- low-level PDF tokenizing

def skip_ws_comments(data, pos):
    n = len(data)
    while pos < n:
        c = data[pos]
        if c in b"\x00\t\n\f\r ":
            pos += 1
        elif c == ord("%"):
            j = data.find(b"\n", pos)
            pos = n if j == -1 else j + 1
        else:
            break
    return pos


def scan_literal_string(data, pos):
    i = pos + 1
    depth = 1
    n = len(data)
    while i < n:
        c = data[i]
        if c == ord("\\"):
            i = min(i + 2, n)
            continue
        if c == ord("("):
            depth += 1
        elif c == ord(")"):
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    return n


def scan_hex_string(data, pos):
    i = data.find(b">", pos + 1)
    return len(data) if i == -1 else i + 1


def scan_name(data, pos):
    i = pos + 1
    n = len(data)
    while i < n and data[i] not in b"\x00\t\n\f\r ()<>[]{}/%":
        i += 1
    return i


def scan_primitive(data, pos):
    m = re.match(rb"\d+\s+\d+\s+R(?![A-Za-z0-9/])", data[pos:pos + 64])
    if m:
        return pos + m.end()
    m = re.match(rb"[+-]?(?:\d+\.?\d*|\.\d+)", data[pos:pos + 64])
    if m:
        return pos + m.end()
    i = pos
    n = len(data)
    while i < n and data[i] not in b"\x00\t\n\f\r ()<>[]{}/%":
        i += 1
    # Guarantee progress even for stray delimiter characters.
    return max(i, pos + 1)


def scan_object(data, pos):
    """Return the position just after one complete PDF object starting at pos."""
    pos = skip_ws_comments(data, pos)
    if pos >= len(data):
        return pos
    c = data[pos]
    if c == ord("("):
        return scan_literal_string(data, pos)
    if c == ord("<"):
        if data[pos + 1:pos + 2] == b"<":
            pos += 2
            while True:
                pos = skip_ws_comments(data, pos)
                if pos >= len(data):
                    return pos
                if data[pos:pos + 2] == b">>":
                    return pos + 2
                c2 = data[pos]
                if c2 == ord("("):
                    pos = scan_literal_string(data, pos)
                elif c2 == ord("<"):
                    pos = scan_object(data, pos)
                elif c2 == ord("["):
                    pos = scan_object(data, pos)
                elif c2 == ord("]"):
                    pos += 1
                elif c2 == ord(">"):
                    pos += 1
                else:
                    pos = scan_primitive(data, pos)
        else:
            return scan_hex_string(data, pos)
    if c == ord("["):
        pos += 1
        while True:
            pos = skip_ws_comments(data, pos)
            if pos >= len(data):
                return pos
            if data[pos] == ord("]"):
                return pos + 1
            pos = scan_object(data, pos)
    if c == ord("/"):
        return scan_name(data, pos)
    # Stray closers/delimiters: advance past them rather than looping.
    if c in b")]>}":
        return pos + 1
    return scan_primitive(data, pos)


def parse_dict_bytes(db):
    """Parse '<< ... >>' bytes into a list of (key, value_bytes) pairs."""
    pairs = []
    pos = skip_ws_comments(db, 0)
    if db[pos:pos + 2] != b"<<":
        return pairs
    pos += 2
    while True:
        pos = skip_ws_comments(db, pos)
        if pos >= len(db) or db[pos:pos + 2] == b">>":
            break
        if db[pos] == ord("/"):
            key_end = scan_name(db, pos)
            key = db[pos + 1:key_end]
            vpos = skip_ws_comments(db, key_end)
            vend = scan_object(db, vpos)
            if vend <= vpos:
                raise ParseError("no progress while parsing dict value")
            pairs.append((key, db[vpos:vend]))
            pos = vend
        else:
            newpos = scan_object(db, pos)
            if newpos <= pos:
                raise ParseError("no progress while parsing dict")
            pos = newpos
    return pairs


def dict_get(pairs, key):
    for k, v in pairs:
        if k == key:
            return v
    return None


def ref_of(value):
    if value is None:
        return None
    m = re.match(rb"(\d+)\s+(\d+)\s+R", value.strip())
    return (int(m.group(1)), int(m.group(2))) if m else None


def int_of(value):
    if value is None:
        return None
    m = re.match(rb"(\d+)", value.strip())
    return int(m.group(1)) if m else None


def name_of(value):
    if value is None:
        return None
    value = value.strip()
    return value if value.startswith(b"/") else None


def ints_of(value):
    return [int(x) for x in re.findall(rb"\d+", value or b"")]


# ---------------------------------------------------------------- compression helpers

def inflate(data_bytes):
    try:
        return zlib.decompress(data_bytes)
    except zlib.error:
        return zlib.decompress(data_bytes, -15)


def png_unpredict(data, columns, colors, bpc):
    bpp = max(1, (colors * bpc + 7) // 8)
    rowlen = max(1, (columns * colors * bpc + 7) // 8)
    out = bytearray()
    prev = bytearray(rowlen)
    i = 0
    n = len(data)
    while i < n:
        f = data[i]
        i += 1
        row = bytearray(data[i:i + rowlen])
        i += rowlen
        if len(row) < rowlen:
            row += b"\x00" * (rowlen - len(row))
        if f == 1:
            for j in range(bpp, rowlen):
                row[j] = (row[j] + row[j - bpp]) & 0xFF
        elif f == 2:
            for j in range(rowlen):
                row[j] = (row[j] + prev[j]) & 0xFF
        elif f == 3:
            for j in range(rowlen):
                a = row[j - bpp] if j >= bpp else 0
                row[j] = (row[j] + ((a + prev[j]) >> 1)) & 0xFF
        elif f == 4:
            for j in range(rowlen):
                a = row[j - bpp] if j >= bpp else 0
                b = prev[j]
                c = prev[j - bpp] if j >= bpp else 0
                p = a + b - c
                pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
                pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                row[j] = (row[j] + pr) & 0xFF
        out += row
        prev = row
    return bytes(out)


def decode_stream_data(stream_bytes, pairs):
    filt = dict_get(pairs, b"Filter")
    if filt is not None and filt not in (b"FlateDecode", b"[FlateDecode]"):
        if not (filt.startswith(b"[") and b"FlateDecode" in filt):
            raise ParseError("unsupported stream filter: %r" % filt)
    raw = inflate(stream_bytes)
    dp = dict_get(pairs, b"DecodeParms")
    if dp and dp.startswith(b"<<"):
        dpp = parse_dict_bytes(dp)
        pred = int_of(dict_get(dpp, b"Predictor")) or 1
        if pred >= 10:
            columns = int_of(dict_get(dpp, b"Columns")) or 1
            colors = int_of(dict_get(dpp, b"Colors")) or 1
            bpc = int_of(dict_get(dpp, b"BitsPerComponent")) or 8
            raw = png_unpredict(raw, columns, colors, bpc)
    return raw


# ---------------------------------------------------------------- object access

def read_stream(data, dict_bytes, stream_pos, ctx):
    """Return stream data bytes for an object whose 'stream' keyword is at stream_pos."""
    eol = stream_pos + 6
    if data[eol:eol + 2] == b"\r\n":
        eol += 2
    elif eol < len(data) and data[eol] in (10, 13):
        eol += 1
    pairs = parse_dict_bytes(dict_bytes)
    len_val = dict_get(pairs, b"Length")
    length = None
    if len_val is not None:
        r = ref_of(len_val)
        if r:
            if ctx is not None:
                try:
                    c = ctx_get_content(ctx, r[0])
                    length = int_of(c["dict"].strip())
                except Exception:
                    length = None
        else:
            length = int_of(len_val)
    if length is not None:
        stream_bytes = data[eol:eol + length]
        after = skip_ws_comments(data, eol + length)
        if data[after:after + 9] == b"endstream":
            return stream_bytes
    idx = data.find(b"endstream", eol)
    if idx == -1:
        raise ParseError("endstream not found")
    sb = data[eol:idx]
    while sb.endswith((b"\n", b"\r")):
        sb = sb[:-1]
    return sb


def extract_type1(ctx, objnum, offset):
    data = ctx["data"]
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[offset:offset + 64])
    if not m or int(m.group(1)) != objnum:
        raise ParseError("object %d not found at offset %d" % (objnum, offset))
    bs = offset + m.end()
    bs = skip_ws_comments(data, bs)
    if data[bs:bs + 2] == b"<<":
        dict_end = scan_object(data, bs)
        dict_bytes = data[bs:dict_end]
        sk = skip_ws_comments(data, dict_end)
        if data[sk:sk + 6] == b"stream":
            return {"kind": "stream", "dict": dict_bytes,
                    "stream": read_stream(data, dict_bytes, sk, ctx)}
        eo = data.find(b"endobj", dict_end)
        if eo == -1:
            raise ParseError("endobj not found for object %d" % objnum)
        return {"kind": "dict", "dict": data[bs:eo].rstrip(b"\x00\t\n\f\r ")}
    eo = data.find(b"endobj", bs)
    if eo == -1:
        raise ParseError("endobj not found for object %d" % objnum)
    return {"kind": "dict", "dict": data[bs:eo].rstrip(b"\x00\t\n\f\r ")}


def ctx_get_content(ctx, num):
    cache = ctx["cache"]
    if num in cache:
        return cache[num]
    entry = ctx["objmap"].get(num)
    if entry is None:
        raise ParseError("object %d not present in xref" % num)
    if entry[0] == "direct":
        content = extract_type1(ctx, num, entry[1])
    else:
        stmnum, idx = entry[1], entry[2]
        ctx["skipped"].add(stmnum)
        stm = ctx_get_content(ctx, stmnum)
        if stm["kind"] != "stream":
            raise ParseError("object stream %d is not a stream" % stmnum)
        pairs = parse_dict_bytes(stm["dict"])
        n = int_of(dict_get(pairs, b"N")) or 0
        first = int_of(dict_get(pairs, b"First")) or 0
        raw = decode_stream_data(stm["stream"], pairs)
        toks = re.findall(rb"\d+", raw[:first])
        offs = [int(toks[i + 1]) for i in range(0, min(2 * n, len(toks) - 1), 2)]
        if idx >= len(offs):
            raise ParseError("object stream index out of range (obj %d)" % num)
        start = first + offs[idx]
        end = scan_object(raw, start)
        content = {"kind": "dict", "dict": raw[start:end].strip()}
    cache[num] = content
    return content


# ---------------------------------------------------------------- xref parsing

def parse_classic_xref(data, pos):
    objmap = {}
    p = data.find(b"xref", pos)
    if p == -1:
        raise ParseError("classic xref not found at %d" % pos)
    p += 4
    while True:
        prev_p = p
        p = skip_ws_comments(data, p)
        if data[p:p + 7] == b"trailer":
            break
        m = re.match(rb"(\d+)\s+(\d+)\s+", data[p:p + 64])
        if not m:
            break
        start = int(m.group(1))
        count = int(m.group(2))
        p += m.end()
        for _ in range(count):
            p = skip_ws_comments(data, p)
            m2 = re.match(rb"(\d+)\s+(\d+)\s+([nf])", data[p:p + 64])
            if not m2:
                raise ParseError("bad xref entry near %d" % p)
            offset = int(m2.group(1))
            typ = m2.group(3)
            if typ == b"n" and offset > 0:
                objmap[start] = ("direct", offset)
            start += 1
            p += m2.end()
        if p == prev_p:
            raise ParseError("no progress while parsing classic xref")
    t = data.find(b"trailer", p)
    if t == -1:
        raise ParseError("trailer keyword not found")
    ts = data.find(b"<<", t)
    te = data.find(b">>", ts)
    trailer_raw = data[ts:te + 2]
    return objmap, parse_dict_bytes(trailer_raw)


def parse_xref_stream(data, pos):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[pos:pos + 64])
    if not m:
        raise ParseError("xref stream object header not found at %d" % pos)
    xref_objnum = int(m.group(1))
    body_start = pos + m.end()
    bs = skip_ws_comments(data, body_start)
    dict_end = scan_object(data, bs)
    dict_bytes = data[bs:dict_end]
    pairs = parse_dict_bytes(dict_bytes)
    sk = skip_ws_comments(data, dict_end)
    stream_bytes = read_stream(data, dict_bytes, sk, None)
    raw = decode_stream_data(stream_bytes, pairs)
    w = ints_of(dict_get(pairs, b"W")) or [1, 4, 2]
    if len(w) < 2:
        w = [1, 4, 2]
    size = int_of(dict_get(pairs, b"Size")) or 0
    idx_vals = ints_of(dict_get(pairs, b"Index")) or [0, size]
    prev = int_of(dict_get(pairs, b"Prev"))
    elen = sum(w)
    objmap = {}
    p = 0
    for k in range(0, len(idx_vals), 2):
        start = idx_vals[k]
        cnt = idx_vals[k + 1] if k + 1 < len(idx_vals) else 0
        for i in range(cnt):
            if p + elen > len(raw):
                break
            entry = raw[p:p + elen]
            p += elen
            t = 1 if w[0] == 0 else int.from_bytes(entry[:w[0]], "big")
            f2 = 0 if w[1] == 0 else int.from_bytes(entry[w[0]:w[0] + w[1]], "big")
            f3 = 0
            if len(w) > 2 and w[2] > 0:
                f3 = int.from_bytes(entry[w[0] + w[1]:w[0] + w[1] + w[2]], "big")
            onum = start + i
            if t == 1:
                objmap[onum] = ("direct", f2)
            elif t == 2:
                objmap[onum] = ("objstm", f2, f3)
    return objmap, pairs, prev, xref_objnum


def parse_pdf(data):
    m = re.match(rb"%PDF-(\d)\.(\d)", data[:64])
    version_minor = int(m.group(2)) if m else 4
    sms = list(re.finditer(rb"startxref\s+(\d+)", data))
    if not sms:
        raise ParseError("no startxref found")
    xref_pos = int(sms[-1].group(1))
    objmap = {}
    trailer_pairs = None
    skipped = set()
    pos = xref_pos
    seen = set()
    while pos and pos not in seen:
        seen.add(pos)
        if data[pos:pos + 4] == b"xref":
            m2, tp = parse_classic_xref(data, pos)
            prev = int_of(dict_get(tp, b"Prev"))
        else:
            m2, tp, prev, xnum = parse_xref_stream(data, pos)
            skipped.add(xnum)
        for k, v in m2.items():
            if k not in objmap:
                objmap[k] = v
        if trailer_pairs is None:
            trailer_pairs = tp
        pos = prev
    if dict_get(trailer_pairs, b"Encrypt") is not None:
        raise ParseError("encrypted PDFs are not supported")
    root_ref = ref_of(dict_get(trailer_pairs, b"Root"))
    if not root_ref:
        raise ParseError("no /Root in trailer")
    ctx = {"data": data, "objmap": objmap, "trailer": trailer_pairs,
           "version_minor": version_minor, "cache": {}, "skipped": skipped}
    catalog = ctx_get_content(ctx, root_ref[0])
    cpairs = parse_dict_bytes(catalog["dict"])
    pages_ref = ref_of(dict_get(cpairs, b"Pages"))
    if not pages_ref:
        raise ParseError("no /Pages in catalog")
    ctx["root"] = pages_ref[0]
    return ctx


# ---------------------------------------------------------------- page tree walking

def refs_from_value(ctx, value):
    if value is None:
        return []
    r = ref_of(value)
    if r:
        body = ctx_get_content(ctx, r[0])["dict"].strip()
        if body.startswith(b"["):
            return [int(x.group(1)) for x in re.finditer(rb"(\d+)\s+\d+\s+R", body)]
        return [r[0]]
    return [int(x.group(1)) for x in re.finditer(rb"(\d+)\s+\d+\s+R", value)]


def count_pages_ctx(ctx, node_num, depth=0):
    if depth > 100000:
        raise ParseError("page tree too deep (possible cycle)")
    content = ctx_get_content(ctx, node_num)
    pairs = parse_dict_bytes(content["dict"])
    typ = name_of(dict_get(pairs, b"Type"))
    if typ == b"Page":
        return 1
    kids = refs_from_value(ctx, dict_get(pairs, b"Kids"))
    return sum(count_pages_ctx(ctx, k, depth + 1) for k in kids)


# ---------------------------------------------------------------- serialization helpers

def rewrite_refs(data, mapping):
    """Copy bytes verbatim, replacing 'old 0 R' references outside strings/comments."""
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        c = data[i]
        if c == ord("%"):
            j = data.find(b"\n", i)
            j = n if j == -1 else j
            out += data[i:j]
            i = j
        elif c == ord("("):
            j = scan_literal_string(data, i)
            out += data[i:j]
            i = j
        elif c == ord("<"):
            if data[i + 1:i + 2] == b"<":
                out += data[i:i + 1]
                i += 1
            else:
                j = scan_hex_string(data, i)
                out += data[i:j]
                i = j
        elif c == ord(">") or c == ord("/") or c in b"[]":
            out += data[i:i + 1]
            i += 1
        elif c in b"0123456789+-.":
            m = re.match(rb"(\d+)\s+(\d+)\s+R(?![A-Za-z0-9/])", data[i:i + 64])
            if m and int(m.group(1)) in mapping:
                out += b"%d %d R" % (mapping[int(m.group(1))], int(m.group(2)))
                i += m.end()
                continue
            m2 = re.match(rb"[+-]?(?:\d+\.?\d*|\.\d+)", data[i:i + 64])
            if m2:
                out += data[i:i + m2.end()]
                i += m2.end()
                continue
            out += data[i:i + 1]
            i += 1
        else:
            out += data[i:i + 1]
            i += 1
    return bytes(out)


def set_length(dict_bytes, length):
    m = re.search(rb"/Length\s+(\d+)(?:\s+\d+\s+R)?", dict_bytes)
    repl = b"/Length " + str(length).encode()
    if m:
        return dict_bytes[:m.start()] + repl + dict_bytes[m.end():]
    idx = dict_bytes.rfind(b">>")
    return dict_bytes[:idx] + repl + b" " + dict_bytes[idx:]


def patch_parent(dict_bytes, newroot):
    m = re.search(rb"/Parent\s+\d+\s+\d+\s+R", dict_bytes)
    repl = b"/Parent " + str(newroot).encode() + b" 0 R"
    if m:
        return dict_bytes[:m.start()] + repl + dict_bytes[m.end():]
    idx = dict_bytes.rfind(b">>")
    return dict_bytes[:idx] + repl + b" " + dict_bytes[idx:]


# ---------------------------------------------------------------- merge

def build_output(ctxs, total_pages):
    roots = [ctx["root"] for ctx in ctxs]
    entries = []
    for ctx in ctxs:
        for oldnum in sorted(ctx["objmap"]):
            if oldnum in ctx["skipped"]:
                continue
            content = ctx_get_content(ctx, oldnum)
            if oldnum in ctx["skipped"]:
                continue
            entries.append((ctx, oldnum, content))
    mapping = {}
    for i, (_, oldnum, _) in enumerate(entries, start=1):
        mapping[oldnum] = i
    catalog_num = len(entries) + 1
    pages_num = len(entries) + 2

    out = bytearray()
    minor = max(ctx["version_minor"] for ctx in ctxs)
    out += b"%%PDF-1.%d\n" % max(4, minor)
    xref_offsets = {}
    for i, (ctx, oldnum, content) in enumerate(entries, start=1):
        xref_offsets[i] = len(out)
        body = rewrite_refs(content["dict"], mapping)
        if oldnum in roots:
            body = patch_parent(body, pages_num)
        if content["kind"] == "stream":
            sb = content["stream"]
            body = set_length(body, len(sb))
            out += b"%d 0 obj\n" % i + body + b"\nstream\n" + sb + b"\nendstream\nendobj\n"
        else:
            out += b"%d 0 obj\n" % i + body + b"\nendobj\n"
    xref_offsets[catalog_num] = len(out)
    out += (b"%d 0 obj\n<< /Type /Catalog /Pages %d 0 R >>\nendobj\n"
            % (catalog_num, pages_num))
    xref_offsets[pages_num] = len(out)
    kids = b" ".join(b"%d 0 R" % mapping[root] for root in roots)
    out += (b"%d 0 obj\n<< /Type /Pages /Kids [%s] /Count %d >>\nendobj\n"
            % (pages_num, kids, total_pages))
    xref_pos = len(out)
    count = pages_num + 1
    out += b"xref\n0 %d\n" % count
    out += b"0000000000 65535 f \n"
    for i in range(1, count):
        out += b"%010d 00000 n \n" % xref_offsets[i]
    trailer = b"<< /Size %d /Root %d 0 R" % (count, catalog_num)
    info_ref = ref_of(dict_get(ctxs[0]["trailer"], b"Info"))
    if info_ref and info_ref[0] in mapping:
        trailer += b" /Info %d 0 R" % mapping[info_ref[0]]
    trailer += b" >>"
    out += b"trailer\n" + trailer + b"\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    return bytes(out)


def main():
    ctxs = []
    for path in INPUT_FILES:
        log("[stage] reading %s" % path)
        with open(path, "rb") as fh:
            data = fh.read()
        if not data.startswith(b"%PDF-"):
            raise ParseError("%s is not a PDF file" % path)
        log("[stage] parsing %s (%d bytes)" % (path, len(data)))
        ctx = parse_pdf(data)
        log("[stage] counting pages in %s" % path)
        ctx["pages"] = count_pages_ctx(ctx, ctx["root"])
        log("Parsed %s: %d objects, %d page(s), PDF-%d.%d"
            % (path, len(ctx["objmap"]), ctx["pages"], 1, ctx["version_minor"]))
        ctxs.append(ctx)

    total_pages = sum(c["pages"] for c in ctxs)
    log("[stage] building merged output")
    result = build_output(ctxs, total_pages)
    with open(TMP_FILE, "wb") as fh:
        fh.write(result)
    os.replace(TMP_FILE, OUTPUT_FILE)

    log("[stage] validating merged output")
    with open(OUTPUT_FILE, "rb") as fh:
        check_data = fh.read()
    check_ctx = parse_pdf(check_data)
    check_pages = count_pages_ctx(check_ctx, check_ctx["root"])
    assert check_pages == total_pages, (
        "validation failed: merged page count %d != expected %d" % (check_pages, total_pages))
    log("Created %s (%d bytes) with %d page(s); validation passed."
        % (OUTPUT_FILE, len(result), check_pages))
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as exc:  # noqa: BLE001 - report and exit cleanly
        if os.path.exists(TMP_FILE):
            os.remove(TMP_FILE)
        print("ERROR: %s" % exc, file=sys.stderr)
        sys.exit(1)

